15	pub struct EnvData {
16	    pub vars: RefCell<Vec<Value>>,
17	    pub parent: Option<Env>,
18	    pub info: Option<Rc<ScopeInfo>>,
19	    pub with_obj: Option<Obj>,
20	    pub extra: RefCell<Vec<(JsStr, Value)>>,
21	}
22	
23	#[derive(Clone)]
24	pub struct Env(pub Rc<EnvData>);
25	
26	impl Env {
27	    pub fn new(info: Rc<ScopeInfo>, parent: Option<Env>) -> Env {
28	        let vals = info
29	            .kinds
30	            .iter()
31	            .map(|k| match k {
32	                BindKind::Let | BindKind::Const | BindKind::Class => Value::Empty,
33	                _ => Value::Undefined,
34	            })
35	            .collect();
36	        Env(Rc::new(EnvData { vars: RefCell::new(vals), parent, info: Some(info), with_obj: None, extra: RefCell::new(Vec::new()) }))
37	    }
38	    pub fn new_with(obj: Obj, parent: Option<Env>) -> Env {
39	        Env(Rc::new(EnvData { vars: RefCell::new(Vec::new()), parent, info: None, with_obj: Some(obj), extra: RefCell::new(Vec::new()) }))
40	    }
41	    pub fn new_empty(parent: Option<Env>) -> Env {
42	        Env(Rc::new(EnvData { vars: RefCell::new(Vec::new()), parent, info: None, with_obj: None, extra: RefCell::new(Vec::new()) }))
43	    }
44	    #[inline]
45	    pub fn ancestor(&self, depth: u16) -> &Env {
46	        let mut e = self;
47	        for _ in 0..depth {
48	            e = e.0.parent.as_ref().expect("env depth");
49	        }
50	        e
51	    }
52	}
