210	    pub fn enter(&mut self) -> JsResult<()> {
211	        if self.depth + self.depth_offset >= MAX_DEPTH {
212	            return self.throw_range("Maximum call stack size exceeded");
213	        }
214	        self.depth += 1;
215	        Ok(())
216	    }
217	
218	    pub fn call_obj(&mut self, o: &Obj, this: Value, args: &[Value]) -> JsResult<Value> {
219	        enum K {
220	            Closure(Rc<FunctionCode>, Option<Env>, Option<Obj>, bool),
221	            Native(NativeFn),
222	            Bound(Obj, Value, Vec<Value>),
223	            Proxy,
224	            NotCallable,
225	        }
226	        let k = {
227	            let b = o.borrow();
228	            match &b.kind {
229	                ObjKind::Closure(c) => K::Closure(c.code.clone(), c.env.clone(), c.home_object.clone(), c.is_class_ctor),
230	                ObjKind::Native(n) => K::Native(n.f),
231	                ObjKind::Bound(bf) => K::Bound(bf.target.clone(), bf.this.clone(), bf.args.clone()),
232	                ObjKind::Proxy(p) if p.callable => K::Proxy,
233	                _ => K::NotCallable,
234	            }
235	        };
236	        match k {
237	            K::Closure(code, env, home, is_class) => {
238	                if is_class {
239	                    return self.throw_type("Class constructor cannot be invoked without 'new'");
240	                }
241	                self.call_closure(o, code, env, home, this, args, Value::Undefined)
242	            }
243	            K::Native(f) => {
244	                self.enter()?;
245	                let r = f(self, &Args { this, args, callee: o, new_target: None });
246	                self.depth -= 1;
247	                r
248	            }
249	            K::Bound(target, bthis, bargs) => {
250	                let mut all = bargs;
251	                all.extend_from_slice(args);
252	                self.enter()?;
253	                let r = self.call_obj(&target, bthis, &all);
254	                self.depth -= 1;
255	                r
256	            }
257	            K::Proxy => crate::builtins::proxy::proxy_call(self, o, this, args),
258	            K::NotCallable => self.throw_type("object is not a function"),
259	        }
260	    }
261	
262	    #[allow(clippy::too_many_arguments)]
263	    pub fn call_closure(
264	        &mut self,
265	        f: &Obj,
266	        code: Rc<FunctionCode>,
267	        env: Option<Env>,
268	        home: Option<Obj>,
269	        this: Value,
270	        args: &[Value],
271	        new_target: Value,
272	    ) -> JsResult<Value> {
273	        let this = if code.strict || code.is_arrow {
274	            this
275	        } else {
276	            match this {
277	                Value::Undefined | Value::Null => Value::Obj(self.global.clone()),
278	                Value::Obj(_) => this,
279	                other => Value::Obj(self.to_object(&other)?),
280	            }
281	        };
282	        let mut frame = Frame::new(code.clone(), env, this, Some(f.clone()), new_target, args.to_vec(), home);
283	        if code.is_generator {
284	            return self.start_generator(f, frame);
285	        }
286	        if code.is_async {
287	            return Ok(self.start_async(frame));
288	        }
289	        self.enter()?;
290	        self.trace.push(TraceEntry { name: trace_name(&code) });
291	        let r = self.run_frame(&mut frame);
292	        self.trace.pop();
293	        self.depth -= 1;
294	        match r {
295	            Ok(Completion::Return(v)) => Ok(v),
296	            Ok(_) => Ok(Value::Undefined),
297	            Err(e) => Err(e),
298	        }
299	    }
