301	    pub fn construct(&mut self, f: &Value, args: &[Value], new_target: Option<&Value>) -> JsResult<Value> {
302	        let fo = match f {
303	            Value::Obj(o) if o.is_constructor() => o.clone(),
304	            _ => {
305	                let d = self.describe_for_new(f);
306	                return self.throw_type(format!("{} is not a constructor", d));
307	            }
308	        };
309	        let nt = new_target.cloned().unwrap_or_else(|| f.clone());
310	        self.construct_obj(&fo, args, nt)
311	    }
