317	    pub fn construct_obj(&mut self, fo: &Obj, args: &[Value], nt: Value) -> JsResult<Value> {
318	        enum K {
319	            Closure(Rc<FunctionCode>, Option<Env>, Option<Obj>, bool, Option<Rc<Vec<ClassField>>>),
320	            Native(NativeFn),
321	            Bound(Obj, Vec<Value>),
322	            Proxy,
323	        }
324	        let k = {
325	            let b = fo.borrow();
326	            match &b.kind {
327	                ObjKind::Closure(c) => K::Closure(c.code.clone(), c.env.clone(), c.home_object.clone(), c.derived, c.fields.clone()),
328	                ObjKind::Native(n) => K::Native(n.f),
329	                ObjKind::Bound(bf) => K::Bound(bf.target.clone(), bf.args.clone()),
330	                ObjKind::Proxy(_) => K::Proxy,
331	                _ => return self.throw_type("object is not a constructor"),
332	            }
333	        };
334	        match k {
335	            K::Closure(code, env, home, derived, fields) => {
336	                let this = if derived {
337	                    Value::Empty
338	                } else {
339	                    let proto = self.get_prototype_from_ctor(&nt, ProtoKind::Object)?;
340	                    let obj = Obj::new(Some(proto), ObjKind::Ordinary);
341	                    if let Some(fl) = &fields {
342	                        self.init_fields(&obj, fl)?;
343	                    }
344	                    Value::Obj(obj)
345	                };
346	                let mut frame = Frame::new(code.clone(), env, this.clone(), Some(fo.clone()), nt, args.to_vec(), home);
347	                self.enter()?;
348	                self.trace.push(TraceEntry { name: trace_name(&code) });
349	                let r = self.run_frame(&mut frame);
350	                self.trace.pop();
351	                self.depth -= 1;
352	                let v = match r? {
353	                    Completion::Return(v) => v,
354	                    _ => Value::Undefined,
355	                };
356	                if let Value::Obj(_) = v {
357	                    return Ok(v);
358	                }
359	                if derived {
360	                    if !v.is_undefined() {
361	                        return self.throw_type("Derived constructors may only return object or undefined");
362	                    }
363	                    if frame.this.is_empty() {
364	                        return self.throw_ref("must call super constructor before accessing 'this' or returning from derived constructor");
365	                    }
366	                    return Ok(frame.this.clone());
367	                }
368	                Ok(this)
369	            }
370	            K::Native(f) => {
371	                self.enter()?;
372	                let nt_obj = nt.as_obj().cloned();
373	                let r = f(self, &Args { this: Value::Undefined, args, callee: fo, new_target: nt_obj });
374	                self.depth -= 1;
375	                r
376	            }
377	            K::Bound(target, bargs) => {
378	                let mut all = bargs;
379	                all.extend_from_slice(args);
380	                let nt = if let Value::Obj(n) = &nt {
381	                    if n.ptr_eq(fo) {
382	                        Value::Obj(target.clone())
383	                    } else {
384	                        nt
385	                    }
386	                } else {
387	                    nt
388	                };
389	                self.construct_obj(&target, &all, nt)
390	            }
391	            K::Proxy => crate::builtins::proxy::proxy_construct(self, fo, args, nt),
392	        }
393	    }
394	
395	    pub fn init_fields(&mut self, obj: &Obj, fields: &Rc<Vec<ClassField>>) -> JsResult<()> {
396	        // private methods first
397	        for f in fields.iter() {
398	            if let FieldKey::PrivateMethod(sym, prop) = &f.key {
399	                let k = PropKey::Sym(sym.clone());
400	                if obj.borrow().props.contains(&k) {
401	                    return self.throw_type("Cannot initialize private methods of class twice on the same object");
402	                }
403	                obj.borrow_mut().props.insert(k, prop.clone());
404	            }
405	        }
406	        for f in fields.iter() {
407	            let v = match &f.init {
408	                Some(init) => self.call_obj(init, Value::Obj(obj.clone()), &[])?,
409	                None => Value::Undefined,
410	            };
411	            match &f.key {
412	                FieldKey::Key(k) => {
413	                    if !self.create_data_property(obj, k.clone(), v)? {
414	                        return self.throw_type(format!("Cannot redefine property: {}", k.to_display()));
415	                    }
416	                }
417	                FieldKey::Private(sym) => {
418	                    let k = PropKey::Sym(sym.clone());
419	                    if obj.borrow().props.contains(&k) {
420	                        return self.throw_type(format!(
421	                            "Cannot initialize {} twice on the same object",
422	                            sym.0.description.as_ref().map(|d| d.to_rust_string()).unwrap_or_default()
423	                        ));
424	                    }
425	                    obj.borrow_mut().props.insert(k, Prop::Data { value: v, flags: WRITABLE });
426	                }
427	                FieldKey::PrivateMethod(..) => {}
428	            }
429	        }
430	        Ok(())
431	    }
