434	
435	    fn start_generator(&mut self, f: &Obj, mut frame: Frame) -> JsResult<Value> {
436	        let code = frame.code.clone();
437	        // prologue runs at call time
438	        self.enter()?;
439	        let r = self.run_frame(&mut frame);
440	        self.depth -= 1;
441	        match r {
442	            Ok(Completion::GenStart) => {}
443	            Ok(_) => {}
444	            Err(e) => return Err(e),
445	        }
446	        frame.is_coroutine = true;
447	        let proto_kind = if code.is_async { ProtoKind::AsyncGenerator } else { ProtoKind::Generator };
448	        let proto = self.get_prototype_from_ctor_prop(f, proto_kind)?;
449	        let obj = if code.is_async {
450	            Obj::new(
451	                Some(proto),
452	                ObjKind::AsyncGenerator(Box::new(AsyncGenData {
453	                    state: GenState::SuspendedStart,
454	                    awaiting_return: false,
455	                    frame: Some(Box::new(frame)),
456	                    queue: VecDeque::new(),
457	                })),
458	            )
459	        } else {
460	            Obj::new(Some(proto), ObjKind::Generator(Box::new(GeneratorData { state: GenState::SuspendedStart, frame: Some(Box::new(frame)) })))
461	        };
462	        Ok(Value::Obj(obj))
463	    }
