465	    /// Resume a sync generator. Returns an iterator result object.
466	    pub fn generator_resume(&mut self, gen: &Obj, mode: ResumeMode, value: Value) -> JsResult<Value> {
467	        let (state, frame) = {
468	            let mut b = gen.borrow_mut();
469	            match &mut b.kind {
470	                ObjKind::Generator(g) => {
471	                    let st = g.state;
472	                    if st == GenState::Executing {
473	                        drop(b);
474	                        return self.throw_type("Generator is already running");
475	                    }
476	                    let fr = if st == GenState::Completed { None } else { g.frame.take() };
477	                    if fr.is_some() {
478	                        g.state = GenState::Executing;
479	                    }
480	                    (st, fr)
481	                }
482	                _ => {
483	                    drop(b);
484	                    return self.throw_type("next method called on incompatible receiver");
485	                }
486	            }
487	        };
488	        let mut frame = match frame {
489	            Some(f) => f,
490	            None => {
491	                return match mode {
492	                    ResumeMode::Next => Ok(self.iter_result(Value::Undefined, true)),
493	                    ResumeMode::Return => Ok(self.iter_result(value, true)),
494	                    ResumeMode::Throw => Err(value),
495	                };
496	            }
497	        };
498	        if state == GenState::SuspendedStart && mode != ResumeMode::Next {
499	            self.set_gen_state(gen, GenState::Completed, None);
500	            return match mode {
501	                ResumeMode::Return => Ok(self.iter_result(value, true)),
502	                _ => Err(value),
503	            };
504	        }
505	        match mode {
506	            ResumeMode::Throw => frame.pending_throw = Some(value),
507	            _ => {
508	                if state != GenState::SuspendedStart {
509	                    frame.stack.push(value);
510	                }
511	            }
512	        }
513	        frame.resume_mode = mode;
514	        if let Err(e) = self.enter() {
515	            self.set_gen_state(gen, GenState::SuspendedYield, Some(frame));
516	            return Err(e);
517	        }
518	        let r = self.run_frame(&mut frame);
519	        self.depth -= 1;
520	        match r {
521	            Ok(Completion::Yield(v)) => {
522	                self.set_gen_state(gen, GenState::SuspendedYield, Some(frame));
523	                Ok(self.iter_result(v, false))
524	            }
525	            Ok(Completion::YieldRaw(v)) => {
526	                self.set_gen_state(gen, GenState::SuspendedYield, Some(frame));
527	                Ok(v)
528	            }
529	            Ok(Completion::Return(v)) => {
530	                self.set_gen_state(gen, GenState::Completed, None);
531	                Ok(self.iter_result(v, true))
532	            }
533	            Ok(_) => {
534	                self.set_gen_state(gen, GenState::Completed, None);
535	                Ok(self.iter_result(Value::Undefined, true))
536	            }
537	            Err(e) => {
538	                self.set_gen_state(gen, GenState::Completed, None);
539	                Err(e)
540	            }
541	        }
542	    }
