544	    fn set_gen_state(&mut self, gen: &Obj, st: GenState, frame: Option<Box<Frame>>) {
545	        if let ObjKind::Generator(g) = &mut gen.borrow_mut().kind {
546	            g.state = st;
547	            g.frame = frame;
548	        }
549	    }
