568	    /// Run/resume an async function coroutine.
569	    pub fn async_step(&mut self, co: &Obj, mode: ResumeMode, value: Value, first: bool) {
570	        let (frame, cap) = {
571	            let mut b = co.borrow_mut();
572	            match &mut b.kind {
573	                ObjKind::AsyncFn(a) => (a.frame.take(), a.capability.clone()),
574	                _ => return,
575	            }
576	        };
577	        let mut frame = match frame {
578	            Some(f) => f,
579	            None => return,
580	        };
581	        if !first {
582	            match mode {
583	                ResumeMode::Throw => frame.pending_throw = Some(value),
584	                _ => frame.stack.push(value),
585	            }
586	        }
587	        let r = if self.enter().is_ok() {
588	            if first {
589	                self.trace.push(TraceEntry { name: trace_name(&frame.code) });
590	            }
591	            let r = self.run_frame(&mut frame);
592	            if first {
593	                self.trace.pop();
594	            }
595	            self.depth -= 1;
596	            r
597	        } else {
598	            Err(self.make_error("RangeError", "Maximum call stack size exceeded"))
599	        };
600	        frame.is_coroutine = true;
601	        match r {
602	            Ok(Completion::Await(v)) => {
603	                if let ObjKind::AsyncFn(a) = &mut co.borrow_mut().kind {
604	                    a.frame = Some(frame);
605	                }
606	                self.await_value(v, co.clone());
607	            }
608	            Ok(Completion::Return(v)) => {
609	                let _ = self.call(&cap.resolve, Value::Undefined, &[v]);
610	            }
611	            Ok(_) => {
612	                let _ = self.call(&cap.resolve, Value::Undefined, &[Value::Undefined]);
613	            }
614	            Err(e) => {
615	                let _ = self.call(&cap.reject, Value::Undefined, &[e]);
616	            }
617	        }
618	    }
