620	    /// Subscribe coroutine `co` to the settlement of `v`.
621	    pub fn await_value(&mut self, v: Value, co: Obj) {
622	        let p = match crate::builtins::promise::promise_resolve_intrinsic(self, v) {
623	            Ok(p) => p,
624	            Err(e) => {
625	                // resume with throw
626	                let job = Job::Reaction(
627	                    Reaction { capability: None, is_reject: true, handler: Handler::Await(co) },
628	                    e,
629	                );
630	                self.jobs.push_back(job);
631	                return;
632	            }
633	        };
634	        crate::builtins::promise::perform_then_internal(self, &p, Handler::Await(co.clone()), Handler::Await(co), None);
635	    }
