637	    pub fn resume_coroutine(&mut self, co: &Obj, mode: ResumeMode, value: Value) {
638	        let is_async_fn = matches!(co.borrow().kind, ObjKind::AsyncFn(_));
639	        if is_async_fn {
640	            self.async_step(co, mode, value, false);
641	        } else {
642	            crate::builtins::generators::async_gen_resume_from_await(self, co, mode, value);
643	        }
644	    }
