646	    // ---------------- main loop ----------------
647	
648	    pub fn run_frame(&mut self, frame: &mut Frame) -> Result<Completion, Value> {
649	        if let Some(e) = frame.pending_throw.take() {
650	            if !self.handle_throw(frame, e.clone()) {
651	                return Err(e);
652	            }
653	        }
654	        loop {
655	            match self.run_inner(frame) {
656	                Ok(c) => return Ok(c),
657	                Err(e) => {
658	                    if !self.handle_throw(frame, e.clone()) {
659	                        return Err(e);
660	                    }
661	                }
662	            }
663	        }
664	    }
665	
666	    fn handle_throw(&mut self, frame: &mut Frame, e: Value) -> bool {
667	        match frame.handlers.pop() {
668	            Some(h) => {
669	                frame.stack.truncate(h.sp as usize);
670	                frame.env = h.env;
671	                frame.stack.push(e);
672	                frame.pc = h.pc as usize;
673	                true
674	            }
675	            None => false,
676	        }
677	    }
678	
679	    fn run_inner(&mut self, frame: &mut Frame) -> Result<Completion, Value> {
680	        let code = frame.code.clone();
681	        let ops = &code.ops;
682	        loop {
683	            let op = ops[frame.pc];
684	            frame.pc += 1;
685	            match op {
686	                Op::Undef => frame.stack.push(Value::Undefined),
687	                Op::Null => frame.stack.push(Value::Null),
688	                Op::True => frame.stack.push(Value::Bool(true)),
689	                Op::False => frame.stack.push(Value::Bool(false)),
690	                Op::Int(i) => frame.stack.push(Value::Num(i as f64)),
691	                Op::Const(i) => frame.stack.push(code.consts[i as usize].clone()),
692	                Op::Empty => frame.stack.push(Value::Empty),
693	                Op::Pop => {
694	                    frame.stack.pop();
695	                }
696	                Op::Dup => {
697	                    let v = frame.stack.last().unwrap().clone();
698	                    frame.stack.push(v);
699	                }
700	                Op::Dup2 => {

700	                Op::Dup2 => {
701	                    let n = frame.stack.len();
702	                    let a = frame.stack[n - 2].clone();
703	                    let b = frame.stack[n - 1].clone();
704	                    frame.stack.push(a);
705	                    frame.stack.push(b);
706	                }
707	                Op::Swap => {
708	                    let n = frame.stack.len();
709	                    frame.stack.swap(n - 1, n - 2);
710	                }
711	                Op::Rot3 => {
