1765	    fn yield_star_step(&mut self, frame: &mut Frame, ret_target: u32, is_async: bool) -> JsResult<Option<Completion>> {
1766	        // stack: [iter next received]; frame.resume_mode tells how we were resumed
1767	        // For async generators the awaited results come back through the received slot with
1768	        // an internal state marker stored in frame (handled by async generator driver).
1769	        let n = frame.stack.len();
1770	        let received = frame.stack[n - 1].clone();
1771	        let next = frame.stack[n - 2].clone();
1772	        let it = frame.stack[n - 3].clone();
1773	        let mode = frame.resume_mode;
1774	        frame.resume_mode = ResumeMode::Next;
1775	        let result = match mode {
1776	            ResumeMode::Next => self.call(&next, it.clone(), &[received])?,
1777	            ResumeMode::Throw => {
1778	                let th = self.get_method(&it, &PropKey::from_str("throw"))?;
1779	                match th {
1780	                    Some(f) => self.call(&f, it.clone(), &[received])?,
1781	                    None => {
1782	                        // close iterator then throw TypeError
1783	                        if is_async {
1784	                            let _ = self.iterator_close(&it);
1785	                        } else {
1786	                            self.iterator_close(&it)?;
1787	                        }
1788	                        return Err(self.make_error("TypeError", "The iterator does not provide a 'throw' method"));
1789	                    }
1790	                }
1791	            }
1792	            ResumeMode::Return => {
1793	                let rf = self.get_method(&it, &PropKey::from_str("return"))?;
1794	                match rf {
1795	                    Some(f) => {
1796	                        let r = self.call(&f, it.clone(), &[received])?;
1797	                        let r = if is_async { self.await_sync_hack(r)? } else { r };
1798	                        let ro = match &r {
1799	                            Value::Obj(o) => o.clone(),
1800	                            _ => return Err(self.make_error("TypeError", "iterator result is not an object")),
1801	                        };
1802	                        let done = self.get(&ro, &self.intr.key_done.clone(), &r)?.truthy();
1803	                        if done {
1804	                            let v = self.get(&ro, &self.intr.key_value.clone(), &r)?;
1805	                            frame.stack.truncate(n - 3);
1806	                            frame.stack.push(v);
1807	                            frame.pc = ret_target as usize;
1808	                            return Ok(None);
1809	                        }
1810	                        // not done: yield the result again
1811	                        frame.pc -= 1;
1812	                        frame.resume_mode = ResumeMode::Next;
1813	                        if is_async {
1814	                            let v = self.get(&ro, &self.intr.key_value.clone(), &r)?;
1815	                            frame.stack.pop();
1816	                            return Ok(Some(Completion::Yield(v)));
1817	                        }
1818	                        frame.stack.pop();
1819	                        return Ok(Some(Completion::YieldRaw(r)));
1820	                    }
1821	                    None => {
1822	                        frame.stack.truncate(n - 3);
1823	                        frame.stack.push(received);
1824	                        frame.pc = ret_target as usize;
1825	                        return Ok(None);
1826	                    }
1827	                }
1828	            }
1829	        };
1830	        let result = if is_async { self.await_sync_hack(result)? } else { result };
1831	        let ro = match &result {
1832	            Value::Obj(o) => o.clone(),
1833	            _ => return Err(self.make_error("TypeError", "iterator result is not an object")),
1834	        };
1835	        let done = self.get(&ro, &self.intr.key_done.clone(), &result)?.truthy();
1836	        if done {
1837	            let v = self.get(&ro, &self.intr.key_value.clone(), &result)?;
1838	            frame.stack.truncate(n - 3);
1839	            frame.stack.push(v);
1840	            return Ok(None);
1841	        }
1842	        // suspend: re-execute this op on resume
1843	        frame.pc -= 1;
1844	        frame.stack.pop(); // received slot is re-pushed on resume
1845	        if is_async {
1846	            let v = self.get(&ro, &self.intr.key_value.clone(), &result)?;
1847	            return Ok(Some(Completion::Yield(v)));
1848	        }
1849	        Ok(Some(Completion::YieldRaw(result)))
1850	    }
