1852	    /// For async yield*: inner results are promises; we resolve already-settled native promises
1853	    /// synchronously when possible (approximation), otherwise drain microtasks until settled.
1854	    fn await_sync_hack(&mut self, v: Value) -> JsResult<Value> {
1855	        let is_p = matches!(&v, Value::Obj(o) if matches!(o.borrow().kind, ObjKind::Promise(_)));
1856	        if !is_p {
1857	            return Ok(v);
1858	        }
1859	        if let Value::Obj(o) = &v {
1860	            loop {
1861	                let st = match &o.borrow().kind {
1862	                    ObjKind::Promise(p) => p.state.clone(),
1863	                    _ => unreachable!(),
1864	                };
1865	                match st {
1866	                    PromiseState::Fulfilled(x) => return Ok(x),
1867	                    PromiseState::Rejected(x) => {
1868	                        if let ObjKind::Promise(p) = &mut o.borrow_mut().kind {
1869	                            p.is_handled = true;
1870	                        }
1871	                        return Err(x);
1872	                    }
1873	                    PromiseState::Pending => {
1874	                        if !self.run_one_job() {
1875	                            return Ok(Value::Undefined);
1876	                        }
1877	                    }
1878	                }
1879	            }
1880	        }
1881	        Ok(v)
1882	    }
