1894	    pub fn run_job(&mut self, job: Job) {
1895	        match job {
1896	            Job::Reaction(r, arg) => crate::builtins::promise::run_reaction(self, r, arg),
1897	            Job::ResolveThenable(p, thenable, then) => crate::builtins::promise::run_resolve_thenable(self, p, thenable, then),
1898	            Job::Callback(f, args) => {
1899	                if let Err(e) = self.call(&f, Value::Undefined, &args) {

1899	                if let Err(e) = self.call(&f, Value::Undefined, &args) {
1900	                    self.report_uncaught(e);
1901	                }
1902	            }
1903	            Job::Native(f, v) => {
1904	                if let Err(e) = f(self, v) {
1905	                    self.report_uncaught(e);
1906	                }
1907	            }
1908	        }
1909	    }
