1931	    pub fn make_closure(&mut self, code: Rc<FunctionCode>, env: Option<Env>, home: Option<Obj>) -> Obj {
1932	        let proto = if code.is_async && code.is_generator {
1933	            self.intr.async_generator_function_proto.clone()
1934	        } else if code.is_generator {
1935	            self.intr.generator_function_proto.clone()
1936	        } else if code.is_async {
1937	            self.intr.async_function_proto.clone()
1938	        } else {
1939	            self.intr.function_proto.clone()
1940	        };
1941	        let is_class = matches!(code.kind, crate::ast::FuncKind::ClassConstructor | crate::ast::FuncKind::DerivedConstructor);
1942	        let derived = code.kind == crate::ast::FuncKind::DerivedConstructor;
1943	        let f = Obj::with_class(
1944	            Some(proto),
1945	            ObjKind::Closure(Box::new(Closure { code: code.clone(), env, home_object: home, fields: None, this_val: None, is_class_ctor: is_class, derived })),
1946	            "Function",
1947	        );
1948	        {
1949	            let mut b = f.borrow_mut();
1950	            b.props.insert(self.intr.key_length.clone(), Prop::Data { value: Value::Num(code.length as f64), flags: CONFIGURABLE });
1951	            b.props.insert(self.intr.key_name.clone(), Prop::Data { value: Value::Str(code.name.clone()), flags: CONFIGURABLE });
1952	        }
1953	        if code.is_generator {
1954	            let pp = if code.is_async { self.intr.async_generator_proto.clone() } else { self.intr.generator_proto.clone() };
1955	            let p = Obj::new(Some(pp), ObjKind::Ordinary);
1956	            f.set_prop(self.intr.key_prototype.clone(), Value::Obj(p), WRITABLE);
1957	        } else if !code.no_prototype && !is_class && !code.is_arrow {
1958	            let p = Obj::new(Some(self.intr.object_proto.clone()), ObjKind::Ordinary);
1959	            p.set_prop(self.intr.key_constructor.clone(), Value::Obj(f.clone()), WC);
1960	            f.set_prop(self.intr.key_prototype.clone(), Value::Obj(p), WRITABLE);
1961	        }
1962	        f
1963	    }
