1984	    fn define_accessor_part(&mut self, o: &Obj, key: PropKey, f: Value, mk: MKind, flags: u8) {
1985	        let fo = f.as_obj().cloned();
1986	        let mut b = o.borrow_mut();
1987	        let existing = b.props.get(&key).cloned();
1988	        let (mut g, mut s) = match existing {
1989	            Some(Prop::Accessor { get, set, .. }) => (get, set),
1990	            _ => (None, None),
1991	        };
