2022	        }
2023	        let cooked: Vec<Value> = t.cooked.iter().map(|c| c.clone().map(Value::Str).unwrap_or(Value::Undefined)).collect();
2024	        let raw: Vec<Value> = t.raw.iter().map(|r| Value::Str(r.clone())).collect();
2025	        let raw_arr = self.new_array(raw);
2026	        let arr = self.new_array(cooked);
2027	        crate::builtins::object::freeze_obj(self, &raw_arr);
2028	        arr.set_prop(PropKey::from_str("raw"), Value::Obj(raw_arr), 0);
2029	        crate::builtins::object::freeze_obj(self, &arr);
2030	        self.template_cache.insert(t.id, arr.clone());
2031	        arr
2032	    }
