2615	        Op::UShr => (to_uint32(x) >> (to_uint32(y) & 31)) as f64,
2616	        Op::BitAnd => (to_int32(x) & to_int32(y)) as f64,
2617	        Op::BitOr => (to_int32(x) | to_int32(y)) as f64,
2618	        Op::BitXor => (to_int32(x) ^ to_int32(y)) as f64,
