2623	pub fn js_fmod(x: f64, y: f64) -> f64 {
2624	    if y.is_infinite() && x.is_finite() {
2625	        return x;
2626	    }
2627	    let r = x % y;
2628	    if r == 0.0 && x.is_sign_negative() {
2629	        -0.0
2630	    } else {
2631	        r
2632	    }
2633	}
