2636	    if y.is_nan() {
2637	        return f64::NAN;
2638	    }
2639	    if y == 0.0 {
2640	        return 1.0;
2641	    }
2642	    if (x == 1.0 || x == -1.0) && y.is_infinite() {
2643	        return f64::NAN;
2644	    }
2645	    x.powf(y)
2646	}
