17	/// Canonical numeric index string check for typed arrays. Returns Some(n) if the key is numeric.
18	pub fn canonical_numeric(key: &PropKey) -> Option<f64> {
19	    let s = match key {
20	        PropKey::Str(s) => s,
21	        _ => return None,
22	    };
23	    if let Some(i) = s.as_array_index() {
24	        return Some(i as f64);
25	    }
26	    let u = s.units();
27	    if u.is_empty() {
28	        return None;
29	    }
30	    let c = u[0];
31	    if !(c == b'-' as u16 || (c >= b'0' as u16 && c <= b'9' as u16) || c == b'I' as u16 || c == b'N' as u16) {
32	        return None;
33	    }
34	    if s.eq_str("-0") {
35	        return Some(-0.0);
36	    }
37	    let n = crate::numconv::string_to_number(u);
38	    let back = crate::numconv::number_to_string(n);
39	    if s.eq_str(&back) {
40	        Some(n)
41	    } else {
42	        None
43	    }
44	}
