47	    // ---------------- prototype / extensibility ----------------
48	
49	    pub fn get_prototype_of(&mut self, o: &Obj) -> JsResult<Option<Obj>> {
50	        if o.is_proxy() {
51	            return proxy::proxy_get_prototype_of(self, o);
52	        }
53	        Ok(o.borrow().proto.clone())
54	    }
55	
56	    pub fn set_prototype_of(&mut self, o: &Obj, p: Option<Obj>) -> JsResult<bool> {
57	        if o.is_proxy() {
58	            return proxy::proxy_set_prototype_of(self, o, p);
59	        }
60	        let cur = o.borrow().proto.clone();
61	        let same = match (&cur, &p) {
62	            (Some(a), Some(b)) => a.ptr_eq(b),
63	            (None, None) => true,
64	            _ => false,
65	        };
66	        if same {
67	            return Ok(true);
68	        }
69	        if !o.borrow().extensible {
70	            return Ok(false);
71	        }
72	        // immutable prototype exotic: Object.prototype
73	        if o.ptr_eq(&self.intr.object_proto) {
74	            return Ok(false);
75	        }
76	        // cycle check
77	        let mut pp = p.clone();
78	        while let Some(x) = pp {
79	            if x.ptr_eq(o) {
80	                return Ok(false);
81	            }
82	            if x.is_proxy() {
83	                break;
84	            }
85	            pp = x.borrow().proto.clone();
86	        }
87	        o.borrow_mut().proto = p;
88	        Ok(true)
89	    }
