91	    pub fn is_extensible(&mut self, o: &Obj) -> JsResult<bool> {
92	        if o.is_proxy() {
93	            return proxy::proxy_is_extensible(self, o);
94	        }
95	        Ok(o.borrow().extensible)
96	    }
