98	    pub fn prevent_extensions(&mut self, o: &Obj) -> JsResult<bool> {
99	        if o.is_proxy() {
100	            return proxy::proxy_prevent_extensions(self, o);
101	        }
102	        let is_ta = matches!(o.borrow().kind, ObjKind::TypedArray(_));
103	        if is_ta {
104	            // length-tracking / resizable-backed typed arrays cannot be made non-extensible
105	            let ok = {
106	                let b = o.borrow();
107	                if let ObjKind::TypedArray(t) = &b.kind {
108	                    let resizable = t.buf.borrow().max_len.is_some();
109	                    !(t.length.is_none() || resizable)
110	                } else {
111	                    true
112	                }
113	            };
114	            if !ok {
115	                return Ok(false);
116	            }
117	        }
118	        o.borrow_mut().extensible = false;
119	        Ok(true)
120	    }
