123	
124	    /// Own property (no proxy traps) as a Prop.
125	    pub fn ordinary_get_own(&mut self, o: &Obj, key: &PropKey) -> Option<Prop> {
126	        let b = o.borrow();
127	        match &b.kind {
128	            ObjKind::Array(a) => {
129	                if key.eq_str("length") {
130	                    return Some(Prop::Data { value: Value::Num(a.len as f64), flags: if a.length_writable { WRITABLE } else { 0 } });
131	                }
132	                if !a.sparse {
133	                    if let Some(i) = key.as_index() {
134	                        return match a.dense.get(i as usize) {
135	                            Some(v) if !v.is_empty() => Some(Prop::Data { value: v.clone(), flags: WEC }),
136	                            _ => None,
137	                        };
138	                    }
139	                }
140	            }
141	            ObjKind::String(s) => {
142	                if let Some(i) = key.as_index() {
143	                    if (i as usize) < s.len() {
144	                        let c = s.units()[i as usize];
145	                        return Some(Prop::Data { value: Value::Str(JsStr::from_units(vec![c])), flags: ENUMERABLE });
146	                    }
147	                }
148	                if key.eq_str("length") {
149	                    return Some(Prop::Data { value: Value::Num(s.len() as f64), flags: 0 });
150	                }
151	            }
152	            ObjKind::TypedArray(t) => {
153	                if let Some(n) = canonical_numeric(key) {
154	                    return ta::ta_get_index(t, n).map(|v| Prop::Data { value: v, flags: WEC });
155	                }
156	            }
157	            ObjKind::Arguments(ad) => {
158	                if let Some(i) = key.as_index() {
159	                    if let Some(Some((env, slot))) = ad.mapped.get(i as usize) {
160	                        if let Some(Prop::Data { flags, .. }) = b.props.get(key) {
161	                            let v = env.0.vars.borrow()[*slot as usize].clone();
162	                            return Some(Prop::Data { value: v, flags: *flags });
163	                        }
164	                    }
165	                }
166	            }
167	            _ => {}
168	        }
169	        b.props.get(key).cloned()
170	    }
