172	    pub fn get_own_property(&mut self, o: &Obj, key: &PropKey) -> JsResult<Option<PropDesc>> {
173	        if o.is_proxy() {
174	            return proxy::proxy_get_own_property(self, o, key);
175	        }
176	        if let ObjKind::Namespace(_) = &o.borrow().kind {
177	            return crate::modules::namespace_get_own(self, o, key);
178	        }
179	        Ok(self.ordinary_get_own(o, key).map(|p| PropDesc::from_prop(&p)))
180	    }
