186	    pub fn has_property(&mut self, o: &Obj, key: &PropKey) -> JsResult<bool> {
187	        let mut cur = o.clone();
188	        loop {
189	            if cur.is_proxy() {
190	                return proxy::proxy_has(self, &cur, key);
191	            }
192	            {
193	                let b = cur.borrow();
194	                match &b.kind {
195	                    ObjKind::TypedArray(t) => {
196	                        if let Some(n) = canonical_numeric(key) {
197	                            return Ok(ta::ta_valid_index(t, n));
198	                        }
199	                    }
200	                    ObjKind::Namespace(_) => {
201	                        drop(b);
202	                        return Ok(crate::modules::namespace_get_own(self, &cur, key)?.is_some());
203	                    }
204	                    _ => {}
205	                }
206	            }
207	            if self.ordinary_get_own(&cur, key).is_some() {
208	                return Ok(true);
209	            }
210	            let p = cur.borrow().proto.clone();
211	            match p {
212	                Some(p) => cur = p,
213	                None => return Ok(false),
214	            }
215	        }
216	    }
