218	    // ---------------- [[Get]] ----------------
219	
220	    pub fn get(&mut self, o: &Obj, key: &PropKey, receiver: &Value) -> JsResult<Value> {
221	        let mut cur = o.clone();
222	        loop {
223	            let r = {
224	                let b = cur.borrow();
225	                let mut special = None;
226	                match &b.kind {
227	                    ObjKind::Proxy(_) => special = Some(GetR::Proxy),
228	                    ObjKind::Array(a) => {
229	                        if !a.sparse {
230	                            if let Some(i) = key.as_index() {
231	                                special = Some(match a.dense.get(i as usize) {
232	                                    Some(v) if !v.is_empty() => GetR::Found(v.clone()),
233	                                    _ => GetR::Next(b.proto.clone()),
234	                                });
235	                            }
236	                        }
237	                        if special.is_none() && key.eq_str("length") {
238	                            special = Some(GetR::Found(Value::Num(a.len as f64)));
239	                        }
240	                    }
241	                    ObjKind::String(s) => {
242	                        if let Some(i) = key.as_index() {
243	                            if (i as usize) < s.len() {
244	                                special = Some(GetR::Found(Value::Str(JsStr::from_units(vec![s.units()[i as usize]]))));
245	                            }
246	                        } else if key.eq_str("length") {
247	                            special = Some(GetR::Found(Value::Num(s.len() as f64)));
248	                        }
249	                    }
250	                    ObjKind::TypedArray(t) => {
251	                        if let Some(n) = canonical_numeric(key) {
252	                            special = Some(GetR::Found(ta::ta_get_index(t, n).unwrap_or(Value::Undefined)));
253	                        }
254	                    }
255	                    ObjKind::Namespace(_) => special = Some(GetR::Namespace),
256	                    ObjKind::Arguments(ad) => {
257	                        if let Some(i) = key.as_index() {
258	                            if let Some(Some((env, slot))) = ad.mapped.get(i as usize) {
259	                                if b.props.contains(key) {
260	                                    special = Some(GetR::Found(env.0.vars.borrow()[*slot as usize].clone()));
261	                                }
262	                            }
263	                        }
264	                    }
265	                    _ => {}
266	                }
267	                match special {
268	                    Some(s) => s,
269	                    None => match b.props.get(key) {
270	                        Some(Prop::Data { value, .. }) => GetR::Found(value.clone()),
271	                        Some(Prop::Accessor { get, .. }) => GetR::Getter(get.clone()),
272	                        None => GetR::Next(b.proto.clone()),
273	                    },
274	                }
275	            };
276	            match r {
277	                GetR::Found(v) => return Ok(v),
278	                GetR::Getter(Some(g)) => return self.call_obj(&g, receiver.clone(), &[]),
279	                GetR::Getter(None) => return Ok(Value::Undefined),
280	                GetR::Next(Some(p)) => cur = p,
281	                GetR::Next(None) => return Ok(Value::Undefined),
282	                GetR::Proxy => return proxy::proxy_get(self, &cur, key, receiver),
283	                GetR::Namespace => return crate::modules::namespace_get(self, &cur, key),
284	            }
285	        }
286	    }
