292	    /// GetV on any value (primitives use their prototype)
293	    pub fn get_prop_of(&mut self, base: &Value, key: &PropKey) -> JsResult<Value> {
294	        match base {
295	            Value::Obj(o) => {
296	                // fast path: own data property on ordinary object
297	                {
298	                    let b = o.borrow();
299	                    if let ObjKind::Ordinary = b.kind {
300	                        if let Some(Prop::Data { value, .. }) = b.props.get(key) {
301	                            return Ok(value.clone());
302	                        }
303	                    }
304	                }
305	                self.get(o, key, base)
306	            }
307	            Value::Str(s) => {
308	                if let Some(i) = key.as_index() {
309	                    if (i as usize) < s.len() {
310	                        return Ok(Value::Str(JsStr::from_units(vec![s.units()[i as usize]])));
311	                    }
312	                } else if key.eq_str("length") {
313	                    return Ok(Value::Num(s.len() as f64));
314	                }
315	                let p = self.intr.string_proto.clone();
316	                self.get(&p, key, base)
317	            }
318	            Value::Num(_) => {
319	                let p = self.intr.number_proto.clone();
320	                self.get(&p, key, base)
321	            }
322	            Value::Bool(_) => {
323	                let p = self.intr.boolean_proto.clone();
324	                self.get(&p, key, base)
325	            }
326	            Value::Sym(_) => {
327	                let p = self.intr.symbol_proto.clone();
328	                self.get(&p, key, base)
329	            }
330	            Value::BigInt(_) => {
331	                let p = self.intr.bigint_proto.clone();
332	                self.get(&p, key, base)
333	            }
334	            Value::Undefined | Value::Null | Value::Empty => {
335	                let what = if base.is_null() { "null" } else { "undefined" };
336	                self.throw_type(format!("cannot read property '{}' of {}", key.to_display(), what))
337	            }
338	        }
339	    }
