341	    pub fn get_elem(&mut self, base: &Value, key: &Value) -> JsResult<Value> {
342	        // fast paths for arrays / typed arrays / strings with numeric keys
343	        if let Value::Num(n) = key {
344	            let n = *n;
345	            if n >= 0.0 && n < 4294967295.0 && n.fract() == 0.0 {
346	                let i = n as usize;
347	                match base {
348	                    Value::Obj(o) => {
349	                        let b = o.borrow();
350	                        match &b.kind {
351	                            ObjKind::Array(a) if !a.sparse => {
352	                                if let Some(v) = a.dense.get(i) {
353	                                    if !v.is_empty() {
354	                                        return Ok(v.clone());
355	                                    }
356	                                }
357	                            }
358	                            ObjKind::TypedArray(t) => {
359	                                return Ok(ta::ta_get_index(t, n).unwrap_or(Value::Undefined));
360	                            }
361	                            _ => {}
362	                        }
363	                    }
364	                    Value::Str(s) => {
365	                        if i < s.len() {
366	                            return Ok(Value::Str(JsStr::from_units(vec![s.units()[i]])));
367	                        }
368	                    }
369	                    _ => {}
370	                }
371	            }
372	        }
373	        if base.is_nullish() {
374	            return self.throw_type("cannot read property of null or undefined");
375	        }
376	        let k = self.to_property_key(key)?;
377	        self.get_prop_of(base, &k)
378	    }
