380	    // ---------------- [[Set]] ----------------
381	
382	    pub fn set(&mut self, o: &Obj, key: PropKey, v: Value, receiver: &Value) -> JsResult<bool> {
383	        enum SetR {
384	            OwnData(bool),
385	            Setter(Option<Obj>),
386	            Next(Option<Obj>),
387	            Proxy,
388	            TypedArray(f64),
389	            Done(bool),
390	        }
391	        // fast path: receiver is o, ordinary object, own writable data property
392	        if let Value::Obj(r) = receiver {
393	            if r.ptr_eq(o) {
394	                let mut b = o.borrow_mut();
395	                match &mut b.kind {
396	                    ObjKind::Ordinary | ObjKind::Closure(_) | ObjKind::Error => {
397	                        if let Some(Prop::Data { value, flags }) = b.props.get_mut(&key) {
398	                            if *flags & WRITABLE != 0 {
399	                                *value = v;
400	                                return Ok(true);
401	                            }
402	                            return Ok(false);
403	                        }
404	                    }
405	                    ObjKind::Array(a) => {
406	                        if !a.sparse {
407	                            if let Some(i) = key.as_index() {
408	                                let i = i as usize;
409	                                if i < a.dense.len() && !a.dense[i].is_empty() {
410	                                    a.dense[i] = v;
411	                                    return Ok(true);
412	                                }
413	                            }
414	                        }
415	                    }
416	                    _ => {}
417	                }
418	            }
419	        }
420	        let mut cur = o.clone();
421	        loop {
422	            let r = {
423	                let b = cur.borrow();
424	                let mut special = None;
425	                match &b.kind {
426	                    ObjKind::Proxy(_) => special = Some(SetR::Proxy),
427	                    ObjKind::Array(a) => {
428	                        if key.eq_str("length") {
429	                            special = Some(SetR::OwnData(a.length_writable));
430	                        } else if !a.sparse {
431	                            if let Some(i) = key.as_index() {
432	                                special = Some(match a.dense.get(i as usize) {
433	                                    Some(x) if !x.is_empty() => SetR::OwnData(true),
434	                                    _ => SetR::Next(b.proto.clone()),
435	                                });
436	                            }
437	                        }
438	                    }
439	                    ObjKind::String(s) => {
440	                        if let Some(i) = key.as_index() {
441	                            if (i as usize) < s.len() {
442	                                special = Some(SetR::OwnData(false));
443	                            }
444	                        } else if key.eq_str("length") {
445	                            special = Some(SetR::OwnData(false));
446	                        }
447	                    }
448	                    ObjKind::TypedArray(_) => {
449	                        if let Some(n) = canonical_numeric(&key) {
450	                            special = Some(SetR::TypedArray(n));
451	                        }
452	                    }
453	                    ObjKind::Namespace(_) => special = Some(SetR::Done(false)),
454	                    _ => {}
455	                }
456	                match special {
457	                    Some(s) => s,
458	                    None => match b.props.get(&key) {
459	                        Some(Prop::Data { flags, .. }) => SetR::OwnData(flags & WRITABLE != 0),
460	                        Some(Prop::Accessor { set, .. }) => SetR::Setter(set.clone()),
461	                        None => SetR::Next(b.proto.clone()),
462	                    },
463	                }
464	            };
465	            match r {
466	                SetR::Done(b) => return Ok(b),
467	                SetR::OwnData(false) => return Ok(false),
468	                SetR::OwnData(true) => return self.set_on_receiver(key, v, receiver),
469	                SetR::Setter(Some(s)) => {
470	                    self.call_obj(&s, receiver.clone(), &[v])?;
471	                    return Ok(true);
472	                }
473	                SetR::Setter(None) => return Ok(false),
474	                SetR::Next(Some(p)) => cur = p,
475	                SetR::Next(None) => return self.set_on_receiver(key, v, receiver),
476	                SetR::Proxy => return proxy::proxy_set(self, &cur, key, v, receiver),
477	                SetR::TypedArray(n) => {
478	                    let same = matches!(receiver, Value::Obj(r) if r.ptr_eq(&cur));
479	                    if same {
480	                        ta::ta_set_index(self, &cur, n, &v)?;
481	                        return Ok(true);
482	                    }
483	                    let valid = match &cur.borrow().kind {
484	                        ObjKind::TypedArray(t) => ta::ta_valid_index(t, n),
485	                        _ => false,
486	                    };
487	                    if !valid {
488	                        return Ok(true);
489	                    }
490	                    return self.set_on_receiver(key, v, receiver);
491	                }
492	            }
493	        }
494	    }
495	
496	    fn set_on_receiver(&mut self, key: PropKey, v: Value, receiver: &Value) -> JsResult<bool> {
497	        let ro = match receiver {
498	            Value::Obj(o) => o.clone(),
499	            _ => return Ok(false),
500	        };
501	        let existing = self.get_own_property(&ro, &key)?;
502	        match existing {
503	            Some(d) => {
504	                if d.is_accessor() {
505	                    return Ok(false);
506	                }
507	                if d.writable != Some(true) {
508	                    return Ok(false);
509	                }
510	                // fast in-place update for ordinary objects
511	                if !ro.is_proxy() {
512	                    let mut b = ro.borrow_mut();
513	                    if let ObjKind::Ordinary = b.kind {
514	                        if let Some(Prop::Data { value, .. }) = b.props.get_mut(&key) {
515	                            *value = v;
516	                            return Ok(true);
517	                        }
518	                    }
519	                }
520	                self.define_own_property(&ro, key, PropDesc { value: Some(v), ..Default::default() })
521	            }
522	            None => self.create_data_property(&ro, key, v),
523	        }
524	    }
525	
526	    /// PutValue on any base (throws in strict mode on failure)
527	    pub fn set_prop_of(&mut self, base: &Value, key: PropKey, v: Value, strict: bool) -> JsResult<()> {
528	        match base {
529	            Value::Obj(o) => {
530	                let ok = self.set(o, key.clone(), v, base)?;
531	                if !ok && strict {
532	                    if let ObjKind::Namespace(_) = o.borrow().kind {
533	                        return Ok(());
534	                    }
535	                    let msg = self.set_failure_message(o, &key)?;
536	                    return self.throw_type(msg);
537	                }
538	                Ok(())
539	            }
540	            Value::Undefined | Value::Null | Value::Empty => {
541	                let what = if base.is_null() { "null" } else { "undefined" };
542	                self.throw_type(format!("cannot set property '{}' of {}", key.to_display(), what))
543	            }
544	            _ => {
545	                // primitive base: look up setter on prototype
546	                let proto = self.proto_for_primitive(base);
547	                let ok = self.set(&proto, key.clone(), v, base)?;
548	                if !ok && strict {
549	                    return self.throw_type(format!("Cannot create property '{}' on {} value", key.to_display(), base.type_of()));
550	                }
551	                Ok(())
552	            }
553	        }
554	    }
555	
556	    /// Message for a failed strict-mode [[Set]].
557	    pub fn set_failure_message(&mut self, o: &Obj, key: &PropKey) -> JsResult<String> {
558	        let mut cur = Some(o.clone());
559	        let mut first = true;
560	        while let Some(c) = cur {
561	            if c.is_proxy() {
562	                break;
563	            }
564	            if let Some(p) = self.ordinary_get_own(&c, key) {
565	                match p {
566	                    Prop::Accessor { set: None, .. } => return Ok(format!("cannot set getter-only property '{}'", key.to_display())),
567	                    Prop::Data { flags, .. } if flags & WRITABLE == 0 => return Ok(format!("cannot assign to read-only property '{}'", key.to_display())),
568	                    _ => {
569	                        if first {
570	                            return Ok(format!("cannot assign to read-only property '{}'", key.to_display()));
571	                        }
572	                        break;
573	                    }
574	                }
575	            }
576	            first = false;
577	            cur = c.borrow().proto.clone();
578	        }
579	        if !o.borrow().extensible {
580	            return Ok("cannot add property, object is not extensible".to_string());
581	        }
582	        Ok(format!("cannot assign to read-only property '{}'", key.to_display()))
583	    }
584	
585	    pub fn proto_for_primitive(&self, v: &Value) -> Obj {
586	        match v {
587	            Value::Str(_) => self.intr.string_proto.clone(),
588	            Value::Num(_) => self.intr.number_proto.clone(),
589	            Value::Bool(_) => self.intr.boolean_proto.clone(),
590	            Value::Sym(_) => self.intr.symbol_proto.clone(),
591	            Value::BigInt(_) => self.intr.bigint_proto.clone(),
592	            _ => self.intr.object_proto.clone(),
593	        }
594	    }
595	
596	    pub fn set_elem(&mut self, base: &Value, key: &Value, v: Value, strict: bool) -> JsResult<()> {
597	        if let (Value::Obj(o), Value::Num(n)) = (base, key) {
598	            let n = *n;
599	            if n >= 0.0 && n < 4294967295.0 && n.fract() == 0.0 {
600	                let i = n as usize;
601	                let mut b = o.borrow_mut();
602	                let ext = b.extensible;
603	                match &mut b.kind {
604	                    ObjKind::Array(a) if !a.sparse => {
605	                        if i < a.dense.len() {
606	                            if !a.dense[i].is_empty() || ext {
607	                                a.dense[i] = v;
608	                                return Ok(());
609	                            }
610	                        } else if i == a.dense.len() && ext && a.length_writable && a.dense.len() as u32 == a.len {
611	                            a.dense.push(v);
612	                            a.len += 1;
613	                            return Ok(());
614	                        }
615	                    }
616	                    ObjKind::TypedArray(_) => {
617	                        drop(b);
618	                        ta::ta_set_index(self, o, n, &v)?;
619	                        return Ok(());
620	                    }
621	                    _ => {}
622	                }
623	            }
624	        }
625	        if base.is_nullish() {
626	            return self.throw_type("cannot access property of null or undefined");
627	        }
628	        let k = self.to_property_key(key)?;
629	        self.set_prop_of(base, k, v, strict)
630	    }
