632	    // ---------------- [[DefineOwnProperty]] ----------------
633	
634	    pub fn create_data_property(&mut self, o: &Obj, key: PropKey, v: Value) -> JsResult<bool> {
635	        // fast path for ordinary extensible objects with no existing property
636	        {
637	            let mut b = o.borrow_mut();
638	            if b.extensible {
639	                if let ObjKind::Ordinary = b.kind {
640	                    match b.props.get_mut(&key) {
641	                        None => {
642	                            b.props.insert(key, Prop::Data { value: v, flags: WEC });
643	                            return Ok(true);
644	                        }
645	                        Some(Prop::Data { value, flags }) if *flags & CONFIGURABLE != 0 => {
646	                            *value = v;
647	                            *flags = WEC;
648	                            return Ok(true);
649	                        }
650	                        _ => {}
651	                    }
652	                }
653	            }
654	        }
655	        self.define_own_property(o, key, PropDesc::data(v, WEC))
656	    }
657	
658	    pub fn create_data_property_or_throw(&mut self, o: &Obj, key: PropKey, v: Value) -> JsResult<()> {
659	        if !self.create_data_property(o, key.clone(), v)? {
660	            return self.throw_type(format!("Cannot redefine property: {}", key.to_display()));
661	        }
662	        Ok(())
663	    }
664	
665	    pub fn define_property_or_throw(&mut self, o: &Obj, key: PropKey, desc: PropDesc) -> JsResult<()> {
666	        if !self.define_own_property(o, key.clone(), desc)? {
667	            return self.throw_type(format!("Cannot redefine property: {}", key.to_display()));
668	        }
669	        Ok(())
670	    }
671	
672	    pub fn define_own_property(&mut self, o: &Obj, key: PropKey, desc: PropDesc) -> JsResult<bool> {
673	        enum Kind {
674	            Ordinary,
675	            Array,
676	            TypedArray,
677	            Proxy,
678	            StringObj(usize),
679	            Namespace,
680	            Arguments,
681	        }
682	        let kind = match &o.borrow().kind {
683	            ObjKind::Array(_) => Kind::Array,
684	            ObjKind::TypedArray(_) => Kind::TypedArray,
685	            ObjKind::Proxy(_) => Kind::Proxy,
686	            ObjKind::String(s) => Kind::StringObj(s.len()),
687	            ObjKind::Namespace(_) => Kind::Namespace,
688	            ObjKind::Arguments(_) => Kind::Arguments,
689	            _ => Kind::Ordinary,
690	        };
691	        match kind {
692	            Kind::Proxy => proxy::proxy_define_own_property(self, o, key, desc),
693	            Kind::Array => self.array_define_own_property(o, key, desc),
694	            Kind::TypedArray => {
695	                if let Some(n) = canonical_numeric(&key) {
696	                    return ta::ta_define_own_property(self, o, n, desc);
697	                }
698	                Ok(self.ordinary_define_own_property(o, key, desc))
699	            }
700	            Kind::StringObj(len) => {
701	                if let Some(i) = key.as_index() {
702	                    if (i as usize) < len {
703	                        let cur = self.ordinary_get_own(o, &key);
704	                        return Ok(validate_and_apply(None, &key, false, &desc, cur));
705	                    }
706	                }
707	                if key.eq_str("length") {
708	                    let cur = self.ordinary_get_own(o, &key);
709	                    return Ok(validate_and_apply(None, &key, false, &desc, cur));
710	                }
711	                Ok(self.ordinary_define_own_property(o, key, desc))
712	            }
713	            Kind::Namespace => crate::modules::namespace_define(self, o, &key, &desc),
714	            Kind::Arguments => {
715	                // unmap on accessor or non-writable definitions
716	                let r = self.ordinary_define_own_property(o, key.clone(), desc.clone());
717	                if r {
718	                    if let Some(i) = key.as_index() {
719	                        let mut b = o.borrow_mut();
720	                        if let ObjKind::Arguments(ad) = &mut b.kind {
721	                            if let Some(Some((env, slot))) = ad.mapped.get(i as usize).cloned() {
722	                                if desc.is_accessor() {
723	                                    ad.mapped[i as usize] = None;
724	                                } else {
725	                                    if let Some(v) = &desc.value {
726	                                        env.0.vars.borrow_mut()[slot as usize] = v.clone();
727	                                    }
728	                                    if desc.writable == Some(false) {
729	                                        ad.mapped[i as usize] = None;
730	                                    }
731	                                }
732	                            }
733	                        }
734	                    }
735	                }
736	                Ok(r)
737	            }
738	            Kind::Ordinary => Ok(self.ordinary_define_own_property(o, key, desc)),
739	        }
740	    }
741	
742	    pub fn ordinary_define_own_property(&mut self, o: &Obj, key: PropKey, desc: PropDesc) -> bool {
743	        let cur = o.borrow().props.get(&key).cloned();
744	        let ext = o.borrow().extensible;
745	        validate_and_apply(Some(o), &key, ext, &desc, cur)
746	    }
747	
748	    fn array_to_sparse(o: &Obj) {
749	        let mut b = o.borrow_mut();
750	        let dense = match &mut b.kind {
751	            ObjKind::Array(a) => {
752	                if a.sparse {
753	                    return;
754	                }
755	                a.sparse = true;
756	                std::mem::take(&mut a.dense)
757	            }
758	            _ => return,
759	        };
760	        // indices must come first in key order; PropMap orders numerics separately anyway
761	        let old: Vec<(PropKey, Prop)> = b.props.iter().map(|(k, p)| (k.clone(), p.clone())).collect();
762	        b.props.clear();
763	        for (i, v) in dense.into_iter().enumerate() {
764	            if !v.is_empty() {
765	                b.props.insert(PropKey::from_index(i as u32), Prop::Data { value: v, flags: WEC });
766	            }
767	        }
768	        for (k, p) in old {
769	            b.props.insert(k, p);
770	        }
771	    }
772	
773	    pub fn array_define_own_property(&mut self, o: &Obj, key: PropKey, desc: PropDesc) -> JsResult<bool> {
774	        if key.eq_str("length") {
775	            return self.array_set_length(o, desc);
776	        }
777	        if let Some(idx) = key.as_index() {
778	            let (len, len_writable, sparse) = match &o.borrow().kind {
779	                ObjKind::Array(a) => (a.len, a.length_writable, a.sparse),
780	                _ => unreachable!(),
781	            };
782	            if idx >= len && !len_writable {
783	                return Ok(false);
784	            }
785	            // fast dense path: plain data definition
786	            let plain = desc.get.is_none()
787	                && desc.set.is_none()
788	                && desc.writable != Some(false)
789	                && desc.enumerable != Some(false)
790	                && desc.configurable != Some(false);
791	            if !sparse {
792	                let i = idx as usize;
793	                let exists = match &o.borrow().kind {
794	                    ObjKind::Array(a) => a.dense.get(i).map_or(false, |v| !v.is_empty()),
795	                    _ => false,
796	                };
797	                let full = desc.writable == Some(true) && desc.enumerable == Some(true) && desc.configurable == Some(true);
798	                if plain && (exists || full) && (exists || o.borrow().extensible) {
799	                    let mut b = o.borrow_mut();
800	                    if let ObjKind::Array(a) = &mut b.kind {
801	                        if i < a.dense.len() || i <= a.dense.len() + 64 || i < (a.dense.len() * 2) {
802	                            if let Some(v) = desc.value.clone() {
803	                                if i >= a.dense.len() {
804	                                    a.dense.resize(i + 1, Value::Empty);
805	                                }
806	                                a.dense[i] = v;
807	                            } else if !exists {
808	                                if i >= a.dense.len() {
809	                                    a.dense.resize(i + 1, Value::Empty);
810	                                }
811	                                a.dense[i] = Value::Undefined;
812	                            }
813	                            if idx >= a.len {
814	                                a.len = idx + 1;
815	                            }
816	                            return Ok(true);
817	                        }
818	                    }
819	                }
820	                Self::array_to_sparse(o);
821	            }
822	            let ok = self.ordinary_define_own_property(o, key, desc);
823	            if !ok {
824	                return Ok(false);
825	            }
826	            if let ObjKind::Array(a) = &mut o.borrow_mut().kind {
827	                if idx >= a.len {
828	                    a.len = idx + 1;
829	                }
830	            }
831	            return Ok(true);
832	        }
833	        Ok(self.ordinary_define_own_property(o, key, desc))
834	    }
835	
836	    fn array_set_length(&mut self, o: &Obj, desc: PropDesc) -> JsResult<bool> {
837	        if desc.is_accessor() {
838	            return Ok(false);
839	        }
840	        let (old_len, writable) = match &o.borrow().kind {
841	            ObjKind::Array(a) => (a.len, a.length_writable),
842	            _ => unreachable!(),
843	        };
844	        if desc.configurable == Some(true) || desc.enumerable == Some(true) {
845	            return Ok(false);
846	        }
847	        let new_len = match &desc.value {
848	            None => {
849	                if desc.writable == Some(true) && !writable {
850	                    return Ok(false);
851	                }
852	                if desc.writable == Some(false) {
853	                    if let ObjKind::Array(a) = &mut o.borrow_mut().kind {
854	                        a.length_writable = false;
855	                    }
856	                }
857	                return Ok(true);
858	            }
859	            Some(v) => {
860	                let n = self.to_number(v)?;
861	                let u = crate::builtins::number::to_uint32(n);
862	                let n2 = self.to_number(v)?;
863	                if u as f64 != n2 {
864	                    return self.throw_range("Invalid array length");
865	                }
866	                u
867	            }
868	        };
869	        if new_len == old_len {
870	            if desc.writable == Some(true) && !writable {
871	                return Ok(false);
872	            }
873	            if desc.writable == Some(false) {
874	                if let ObjKind::Array(a) = &mut o.borrow_mut().kind {
875	                    a.length_writable = false;
876	                }
877	            }
878	            return Ok(true);
879	        }
880	        if !writable {
881	            return Ok(false);
882	        }
883	        let sparse = matches!(&o.borrow().kind, ObjKind::Array(a) if a.sparse);
884	        if new_len > old_len {
885	            if let ObjKind::Array(a) = &mut o.borrow_mut().kind {
886	                a.len = new_len;
887	                if desc.writable == Some(false) {
888	                    a.length_writable = false;
889	                }
890	            }
891	            return Ok(true);
892	        }
893	        if !sparse {
894	            if let ObjKind::Array(a) = &mut o.borrow_mut().kind {
895	                if (new_len as usize) < a.dense.len() {
896	                    a.dense.truncate(new_len as usize);
897	                }
898	                a.len = new_len;
899	                if desc.writable == Some(false) {
900	                    a.length_writable = false;
901	                }
902	            }
903	            return Ok(true);
904	        }
905	        // sparse: delete indices >= new_len from highest down
906	        let mut idxs: Vec<u32> = o.borrow().props.keys().iter().filter_map(|k| k.as_index()).filter(|i| *i >= new_len).collect();
907	        idxs.sort_unstable_by(|a, b| b.cmp(a));
908	        for i in idxs {
909	            let k = PropKey::from_index(i);
910	            let configurable = o.borrow().props.get(&k).map_or(true, |p| p.configurable());
911	            if !configurable {
912	                if let ObjKind::Array(a) = &mut o.borrow_mut().kind {
913	                    a.len = i + 1;
914	                    if desc.writable == Some(false) {
915	                        a.length_writable = false;
916	                    }
917	                }
918	                return Ok(false);
919	            }
920	            o.borrow_mut().props.remove(&k);
921	        }
922	        if let ObjKind::Array(a) = &mut o.borrow_mut().kind {
923	            a.len = new_len;
924	            if desc.writable == Some(false) {
925	                a.length_writable = false;
926	            }
