1166	                        set: desc.set.clone().and_then(|v| v.as_obj().cloned()),
1167	                        flags: desc.flags() & !WRITABLE,
1168	                    }
1169	                } else {
1170	                    Prop::Data { value: desc.value.clone().unwrap_or(Value::Undefined), flags: desc.flags() }
1171	                };
1172	                o.borrow_mut().props.insert(key.clone(), prop);
