pub fn get_iterator(&mut self, v: &Value) -> JsResult<(Obj, Value)> {
    let m = self.get_prop_of_for_iter(v)?;
    let m = match m {
        Some(m) => m,
        None => return self.throw_type("value is not iterable"),
    };
    self.get_iterator_from_method(v, &m)
}

fn get_prop_of_for_iter(&mut self, v: &Value) -> JsResult<Option<Value>> {
    if v.is_nullish() {
        return self.throw_type("value is not iterable");
    }
    let f = self.get_prop_of(v, &PropKey::Sym(self.intr.sym_iterator.clone()))?;
    if f.is_nullish() {
        return Ok(None);
    }
    if !f.is_callable() {
        return self.throw_type("value is not iterable");
    }
    Ok(Some(f))
}

pub fn get_iterator_from_method(&mut self, v: &Value, m: &Value) -> JsResult<(Obj, Value)> {
    let it = self.call(m, v.clone(), &[])?;
    let io = match &it {
        Value::Obj(o) => o.clone(),
        _ => return self.throw_type("Result of the Symbol.iterator method is not an object"),
    };
    let next = self.get(&io, &self.intr.key_next.clone(), &it)?;
    Ok((io, next))
}

pub fn get_async_iterator(&mut self, v: &Value) -> JsResult<(Obj, Value)> {
    if v.is_nullish() {
        return self.throw_type("value is not async iterable");
    }
    let m = self.get_prop_of(v, &PropKey::Sym(self.intr.sym_async_iterator.clone()))?;
    if m.is_nullish() {
        let (it, next) = self.get_iterator(v)?;
        return Ok(crate::builtins::iterator::create_async_from_sync(self, it, next));
    }
    if !m.is_callable() {
        return self.throw_type("value is not async iterable");
    }
    self.get_iterator_from_method(v, &m)
}

