1	// Code generator: AST -> bytecode, using resolver scope information.
2	
3	use crate::ast::*;
4	use crate::bytecode::*;
5	use crate::resolver::{is_function_like, RScope, Resolver, ScopeKind};
6	use crate::value::{JsStr, Value};
7	use crate::value::PropKey as VKey;
8	use std::collections::HashMap;
9	use std::rc::Rc;
10	
11	#[derive(Debug)]
12	pub struct CompileError {
13	    pub msg: String,
14	    pub line: u32,
15	}
16	
17	type CResult<T> = Result<T, CompileError>;
18	
19	#[derive(Clone, Copy, PartialEq, Eq, Debug)]
20	struct Label(u32);
21	
22	#[derive(Clone, Copy, Debug)]
23	enum Storage {
24	    Local(u32),
25	    Env(u32),
26	}
27	
28	struct CScope {
29	    rid: usize,
30	    has_env: bool,
31	    names: Vec<(Rc<str>, Storage, BindKind)>,
32	    is_with: bool,
33	    /// function scope with sloppy direct eval
34	    dyn_eval: bool,
35	}
36	
37	enum Ctl<'a> {
38	    Loop { labels: Vec<Rc<str>>, brk: Label, cont: Label },
39	    Breakable { labels: Vec<Rc<str>>, brk: Label },
40	    Scope,
41	    Try { finalizer: Option<&'a Block>, scope_depth: usize },
42	    Iter { is_async: bool },
43	    Stack(u32),
44	}
45	
46	struct FuncState<'a> {
47	    ops: Vec<Op>,
48	    consts: Vec<Value>,
49	    keys: Vec<VKey>,
50	    key_index: HashMap<String, u32>,
51	    funcs: Vec<Rc<FunctionCode>>,
52	    scope_infos: Vec<Rc<ScopeInfo>>,
53	    templates: Vec<Rc<TemplateData>>,
54	    regexps: Vec<(JsStr, JsStr)>,
55	    strings: Vec<JsStr>,
56	    nlocals: u32,
57	    scopes: Vec<CScope>,
58	    ctl: Vec<Ctl<'a>>,
59	    label_pos: Vec<Option<u32>>,
60	    fixups: Vec<(usize, Label)>,
61	    ret_slot: Option<u32>,
62	    completion_slot: Option<u32>,
63	    kind: FuncKind,
64	    is_arrow: bool,
65	    is_async: bool,
66	    is_generator: bool,
67	    strict: bool,
68	    func_rid: usize,
69	    pending_labels: Vec<Rc<str>>,
70	    imports: Vec<Rc<str>>,
71	    opt_end: Option<Label>,
72	    pending_static: Vec<u32>,
73	    scope_marks: Vec<usize>,
74	}
75	
76	pub struct Compiler<'a> {
77	    res: &'a Resolver,
78	    source: Rc<str>,
79	    fs: Vec<FuncState<'a>>,
80	    is_module: bool,
81	    /// eval code: unresolved names are dynamic
82	    eval_mode: bool,
83	    repl: bool,
84	    pub import_names: Vec<Rc<str>>,
85	}
86	
87	fn cerr<T>(msg: impl Into<String>, line: u32) -> CResult<T> {
88	    Err(CompileError { msg: msg.into(), line })
89	}
90	
91	fn set_target(op: &mut Op, t: u32) {
92	    match op {
93	        Op::Jump(x)
94	        | Op::JumpIfFalse(x)
95	        | Op::JumpIfTrue(x)
96	        | Op::JumpIfFalseKeep(x)
97	        | Op::JumpIfTrueKeep(x)
98	        | Op::JumpIfNullishKeep(x)
99	        | Op::JumpIfNotNullishKeep(x)
100	        | Op::JumpIfNotUndef(x)
101	        | Op::JumpIfNullish(x)
102	        | Op::TryStart(x)
103	        | Op::IterNext(x)
104	        | Op::ForInNext(x)
105	        | Op::GenResume(x)
106	        | Op::AsyncIterCheck(x)
107	        | Op::YieldStar(x, _) => *x = t,
108	        _ => panic!("not a jump op: {:?}", op),
109	    }
110	}
111	
112	fn units(s: &str) -> Vec<u16> {
113	    s.encode_utf16().collect()
114	}
115	
116	fn propkey_static_name(k: &PropKey) -> Option<String> {
117	    match k {
118	        PropKey::Ident(n) => Some(n.to_string()),
119	        PropKey::Str(s) => Some(String::from_utf16_lossy(s)),
120	        PropKey::Num(n) => Some(crate::numconv::number_to_string(*n)),
121	        _ => None,
122	    }
123	}
124	
125	impl<'a> Compiler<'a> {
126	    pub fn new(res: &'a Resolver, source: Rc<str>, is_module: bool) -> Compiler<'a> {
127	        Compiler { res, source, fs: Vec::new(), is_module, eval_mode: false, repl: false, import_names: Vec::new() }
128	    }
129	
130	    fn f(&mut self) -> &mut FuncState<'a> {
131	        self.fs.last_mut().unwrap()
132	    }
133	
134	    fn rscope(&self, id: usize) -> &'a RScope {
135	        &self.res.scopes[id]
136	    }
137	
138	    // ---------- emission helpers ----------
139	
140	    fn emit(&mut self, op: Op) -> usize {
141	        let f = self.f();
142	        f.ops.push(op);
143	        f.ops.len() - 1
144	    }
145	
146	    fn new_label(&mut self) -> Label {
147	        let f = self.f();
148	        f.label_pos.push(None);
149	        Label((f.label_pos.len() - 1) as u32)
150	    }
151	
152	    fn place(&mut self, l: Label) {
153	        let f = self.f();
154	        f.label_pos[l.0 as usize] = Some(f.ops.len() as u32);
155	    }
156	
157	    fn emit_jump(&mut self, op: Op, l: Label) -> usize {
158	        let i = self.emit(op);
159	        self.f().fixups.push((i, l));
160	        i
161	    }
162	
163	    fn key_idx(&mut self, name: &str) -> u32 {
164	        let f = self.f();
165	        if let Some(i) = f.key_index.get(name) {
166	            return *i;
167	        }
168	        let i = f.keys.len() as u32;
169	        f.keys.push(VKey::Str(JsStr::from_str(name)));
170	        f.key_index.insert(name.to_string(), i);
171	        i
172	    }
173	
174	    fn key_idx_units(&mut self, u: &[u16]) -> u32 {
175	        let s = String::from_utf16_lossy(u);
176	        if s.encode_utf16().eq(u.iter().copied()) {
177	            return self.key_idx(&s);
178	        }
179	        let f = self.f();
180	        let i = f.keys.len() as u32;
181	        f.keys.push(VKey::Str(JsStr::from_slice(u)));
182	        i
183	    }
184	
185	    fn const_idx(&mut self, v: Value) -> u32 {
186	        let f = self.f();
187	        // dedupe strings & numbers
188	        for (i, c) in f.consts.iter().enumerate() {
189	            match (c, &v) {
190	                (Value::Num(a), Value::Num(b)) if a.to_bits() == b.to_bits() => return i as u32,
191	                (Value::Str(a), Value::Str(b)) if a == b => return i as u32,
192	                _ => {}
193	            }
194	            if i > 256 {
195	                break;
196	            }
197	        }
198	        f.consts.push(v);
199	        (f.consts.len() - 1) as u32
200	    }
201	
202	    fn string_idx(&mut self, s: &str) -> u32 {
203	        let f = self.f();
204	        for (i, x) in f.strings.iter().enumerate() {
205	            if x.eq_str(s) {
206	                return i as u32;
207	            }
208	        }
209	        f.strings.push(JsStr::from_str(s));
210	        (f.strings.len() - 1) as u32
211	    }
212	
213	    fn new_local(&mut self) -> u32 {
214	        let f = self.f();
215	        f.nlocals += 1;
216	        f.nlocals - 1
217	    }
218	
219	    fn push_num(&mut self, n: f64) {
220	        if n.fract() == 0.0 && n.abs() < 2147483647.0 && !(n == 0.0 && n.is_sign_negative()) {
221	            self.emit(Op::Int(n as i32));
222	        } else {
223	            let i = self.const_idx(Value::Num(n));
224	            self.emit(Op::Const(i));
225	        }
226	    }
227	
228	    fn push_str(&mut self, s: &[u16]) {
229	        let i = self.const_idx(Value::Str(JsStr::from_slice(s)));
230	        self.emit(Op::Const(i));
231	    }
232	
233	    // ---------- scopes ----------
234	
235	    /// Enter a resolver scope; emits PushScope if any binding is captured.
236	    fn enter_scope(&mut self, rid: usize, force_env: bool) -> bool {
237	        let rs = self.rscope(rid);
238	        let module_scope = rs.kind == ScopeKind::Module;
239	        let mut names = Vec::new();
240	        let mut env_names: Vec<JsStr> = Vec::new();
241	        let mut env_kinds = Vec::new();
242	        for d in &rs.decls {
243	            if d.kind == BindKind::Import {
244	                continue;
245	            }
246	            if d.kind == BindKind::Internal && !d.captured && !force_env && &*d.name != "arguments" && !d.name.starts_with('#') {
247	                // frame-level binding (this/new.target/%func/%home): accessed with frame ops
248	                continue;
249	            }
250	            if d.kind == BindKind::Internal && &*d.name == "arguments" && !rs.uses_arguments && !d.captured && !force_env {
251	                continue;
252	            }
253	            if rs.kind == ScopeKind::Eval && !rs.strict && matches!(d.kind, BindKind::Var | BindKind::Function) {
254	                // sloppy eval: vars live in the caller's variable environment (dynamic)
255	                continue;
256	            }
257	            let captured = d.captured || force_env || module_scope;
258	            if captured {
259	                names.push((d.name.clone(), Storage::Env(env_names.len() as u32), d.kind));
260	                env_names.push(JsStr::from_str(&d.name));
261	                env_kinds.push(d.kind);
262	            } else {
263	                let slot = self.new_local();
264	                names.push((d.name.clone(), Storage::Local(slot), d.kind));
265	            }
266	        }
267	        let has_env = !env_names.is_empty() || rs.kind == ScopeKind::With || (force_env && rs.kind == ScopeKind::Function);
268	        if has_env && rs.kind != ScopeKind::With {
269	            let info = Rc::new(ScopeInfo {
270	                names: env_names,
271	                kinds: env_kinds,
272	                is_function: is_function_like(rs.kind) && rs.kind != ScopeKind::Eval,
273	            });
274	            let f = self.f();
275	            f.scope_infos.push(info);
276	            let idx = (f.scope_infos.len() - 1) as u32;
277	            self.emit(Op::PushScope(idx));
278	        }
279	        let dyn_eval = is_function_like(rs.kind) && rs.has_eval;
280	        self.f().scopes.push(CScope { rid, has_env, names, is_with: rs.kind == ScopeKind::With, dyn_eval });
281	        // TDZ for lexical locals
282	        let mut clears = Vec::new();
283	        for (_, st, k) in &self.f().scopes.last().unwrap().names {
284	            if let Storage::Local(s) = st {
285	                if matches!(k, BindKind::Let | BindKind::Const | BindKind::Class) {
286	                    clears.push(*s);
287	                }
288	            }
289	        }
290	        for s in clears {
291	            self.emit(Op::ClearLocal(s));
292	        }
293	        has_env
294	    }
295	
296	    fn exit_scope(&mut self) {
297	        let s = self.f().scopes.pop().unwrap();
298	        if s.has_env {
299	            self.emit(Op::PopScope);
300	        }
301	    }
302	
303	    // ---------- name resolution ----------
304	
305	    fn resolve(&self, name: &str) -> Resolved {
306	        let mut depth: u16 = 0;
307	        let mut dynamic = false;
308	        let nf = self.fs.len();
309	        for fi in (0..nf).rev() {
310	            let fstate = &self.fs[fi];
311	            for sc in fstate.scopes.iter().rev() {
312	                if sc.is_with {
313	                    dynamic = true;
314	                }
315	                if let Some((_, st, k)) = sc.names.iter().find(|(n, _, _)| &**n == name) {
316	                    if dynamic {
317	                        return Resolved::Dynamic;
318	                    }
319	                    return match st {
320	                        Storage::Local(s) => {
321	                            if fi == nf - 1 {
322	                                Resolved::Local(*s, *k)
323	                            } else {
324	                                Resolved::Dynamic
325	                            }
326	                        }
327	                        Storage::Env(s) => Resolved::Env(depth, *s, *k),
328	                    };
329	                }
330	                // imports (module scope)
331	                if self.rscope(sc.rid).kind == ScopeKind::Module {
332	                    let rs = self.rscope(sc.rid);
333	                    if rs.decls.iter().any(|d| &*d.name == name && d.kind == BindKind::Import) {
334	                        if let Some(i) = self.import_names.iter().position(|n| &**n == name) {
335	                            return Resolved::Import(i as u32);
336	                        }
337	                    }
338	                }
339	                if sc.has_env {
340	                    depth += 1;
341	                }
342	                if sc.dyn_eval {
343	                    dynamic = true;
344	                }
345	                // frame-level internal names stop at the nearest non-arrow function
346	                if (name == "this" || name == "new.target" || name.starts_with('%')) && !dynamic {
347	                    let rs = self.rscope(sc.rid);
348	                    if is_function_like(rs.kind) && !(rs.kind == ScopeKind::Function && rs.is_arrow) {
349	                        return Resolved::Global;
350	                    }
351	                }
352	            }
353	        }
354	        if dynamic || self.eval_mode {
355	            Resolved::Dynamic
356	        } else {
357	            Resolved::Global
358	        }
359	    }
360	
361	    fn tdz_kind(k: BindKind) -> bool {
362	        matches!(k, BindKind::Let | BindKind::Const | BindKind::Class)
363	    }
364	
365	    fn load_name(&mut self, name: &str) {
366	        match self.resolve(name) {
367	            Resolved::Local(s, k) => {
368	                if Self::tdz_kind(k) {
369	                    let n = self.string_idx(name);
370	                    self.emit(Op::GetLocalChk(s, n));
371	                } else {
372	                    self.emit(Op::GetLocal(s));
373	                }
374	            }
375	            Resolved::Env(d, s, k) => {
376	                if Self::tdz_kind(k) || (k == BindKind::Internal && name == "this") {
377	                    let n = self.string_idx(name);
378	                    self.emit(Op::GetEnvChk(d, s, n));
379	                } else {
380	                    self.emit(Op::GetEnv(d, s));
381	                }
382	            }
383	            Resolved::Global => {
384	                let k = self.key_idx(name);
385	                self.emit(Op::GetGlobal(k));
386	            }
387	            Resolved::Dynamic => {
388	                let k = self.key_idx(name);
389	                self.emit(Op::GetName(k));
390	            }
391	            Resolved::Import(i) => {
392	                self.emit(Op::GetImport(i));
393	            }
394	        }
395	    }
396	
397	    /// store top of stack into a variable (value remains on stack)
398	    fn store_name(&mut self, name: &str, line: u32) -> CResult<()> {
399	        let _ = line;
400	        match self.resolve(name) {
401	            Resolved::Local(s, k) => match k {
402	                BindKind::Const | BindKind::Class if k == BindKind::Const => {
403	                    let n = self.string_idx(name);
404	                    self.emit(Op::GetLocalChk(s, n));
405	                    self.emit(Op::Pop);
406	                    self.emit(Op::ThrowConst(n));
407	                }
408	                BindKind::Let | BindKind::Class => {
409	                    let n = self.string_idx(name);
410	                    self.emit(Op::GetLocalChk(s, n));
411	                    self.emit(Op::Pop);
412	                    self.emit(Op::SetLocal(s));
413	                }
414	                BindKind::FuncName => {
415	                    if self.f().strict {
416	                        let n = self.string_idx(name);
417	                        self.emit(Op::ThrowConst(n));
418	                    }
419	                }
420	                _ => {

420	                _ => {
421	                    self.emit(Op::SetLocal(s));
422	                }
423	            },
424	            Resolved::Env(d, s, k) => match k {
425	                BindKind::Const => {
426	                    let n = self.string_idx(name);
427	                    self.emit(Op::GetEnvChk(d, s, n));
428	                    self.emit(Op::Pop);
429	                    self.emit(Op::ThrowConst(n));
430	                }
431	                BindKind::Let | BindKind::Class => {
432	                    let n = self.string_idx(name);
433	                    self.emit(Op::SetEnvChk(d, s, n));
434	                }
435	                BindKind::FuncName => {
436	                    if self.f().strict {
437	                        let n = self.string_idx(name);
438	                        self.emit(Op::ThrowConst(n));
439	                    }
440	                }
441	                _ => {
442	                    self.emit(Op::SetEnv(d, s));
443	                }
444	            },
445	            Resolved::Global => {
446	                let k = self.key_idx(name);
447	                self.emit(Op::SetGlobal(k));
448	            }
449	            Resolved::Dynamic => {
450	                let k = self.key_idx(name);
451	                self.emit(Op::SetName(k));
452	            }
453	            Resolved::Import(_) => {
454	                let n = self.string_idx(name);
455	                self.emit(Op::ThrowConst(n));
456	            }
457	        }
458	        Ok(())
459	    }
460	
461	    /// initialize a binding (declaration); pops the value
462	    fn init_name(&mut self, name: &str) {
463	        match self.resolve(name) {
464	            Resolved::Local(s, _) => {
465	                self.emit(Op::InitLocal(s));
466	            }
467	            Resolved::Env(d, s, _) => {
468	                self.emit(Op::InitEnv(d, s));
469	            }
470	            Resolved::Global => {
471	                // top-level script lexical or var
472	                let k = self.key_idx(name);
473	                self.emit(Op::InitGlobalLex(k));
474	            }
475	            Resolved::Dynamic => {
476	                let k = self.key_idx(name);
477	                self.emit(Op::SetName(k));
478	                self.emit(Op::Pop);
479	            }
480	            Resolved::Import(_) => {
481	                self.emit(Op::Pop);
482	            }
483	        }
484	    }
485	
486	    fn is_global_lexical(&self, name: &str) -> bool {
487	        self.res.global_names_lex.iter().any(|(n, _)| &**n == name)
488	    }
489	
490	    // ---------- program ----------
491	
492	    pub fn compile_script(mut self, p: &'a Program, is_eval: bool, repl: bool, strict_eval_vars: bool) -> CResult<Rc<FunctionCode>> {
493	        let _ = strict_eval_vars;
494	        self.eval_mode = is_eval;
495	        self.repl = repl;
496	        let rid = p.scope.get() as usize;
497	        self.fs.push(FuncState::new(FuncKind::Normal, false, false, false, p.strict, rid));
498	        let completion = if is_eval || repl {
499	            let s = self.new_local();
500	            self.f().completion_slot = Some(s);
501	            Some(s)
502	        } else {
503	            None
504	        };
505	        let rs = self.rscope(rid);
506	        // global declarations for scripts
507	        if rs.kind == ScopeKind::Script {
508	            for (n, _) in &self.res.global_names_lex {
509	                let is_const = self.is_const_lexical(&p.body, n);
510	                let k = self.key_idx(n);
511	                self.emit(Op::DeclareGlobalLex(k, is_const));
512	            }
513	            for (n, _) in &self.res.global_names_var {
514	                let k = self.key_idx(n);
515	                self.emit(Op::DeclareGlobalVar(k));
516	            }
517	        }
518	        self.enter_scope(rid, false);
519	        self.init_internal_bindings(rid);
520	        if rs.kind == ScopeKind::Eval && !p.strict {
521	            // sloppy eval: var declarations go to the caller's variable environment
522	            for d in &rs.decls {
523	                if matches!(d.kind, BindKind::Var | BindKind::Function) {
524	                    let k = self.key_idx(&d.name);
525	                    self.emit(Op::DeclareGlobalVar(k));
526	                }
527	            }
528	        }
529	        self.hoist_functions(&p.body, true)?;
530	        for s in &p.body {
531	            self.compile_stmt(s)?;
532	        }
533	        if let Some(c) = completion {
534	            self.emit(Op::GetLocal(c));
535	        } else {
536	            self.emit(Op::Undef);
537	        }
538	        self.emit(Op::Return);
539	        self.exit_scope_noemit();
540	        let fs = self.fs.pop().unwrap();
541	        let mut code = self.finish(fs, JsStr::empty(), 0, 0, 0, 0, true);
542	        code.is_script = true;
543	        code.is_eval = is_eval;
544	        Ok(Rc::new(code))
545	    }
