551	    fn is_const_lexical(&self, body: &[Stmt], name: &str) -> bool {
552	        for s in body {
553	            if let Stmt::Var(d) = s {
554	                if d.kind == VarKind::Const {
555	                    for decl in &d.decls {
556	                        let mut ns = Vec::new();
557	                        crate::resolver::pattern_names(&decl.target, &mut ns);
558	                        if ns.iter().any(|(n, _)| &**n == name) {
559	                            return true;
560	                        }
561	                    }
562	                }
563	            }
564	        }
565	        false
566	    }
