568	    pub fn compile_module(mut self, p: &'a Program) -> CResult<(Rc<FunctionCode>, Vec<Rc<str>>)> {
569	        let rid = p.scope.get() as usize;
570	        // import bindings in order of declaration
571	        for s in &p.body {
572	            if let Stmt::Import(imp) = s {
573	                if let Some(d) = &imp.default {
574	                    self.import_names.push(d.name.clone());
575	                }
576	                if let Some(ns) = &imp.namespace {
577	                    self.import_names.push(ns.name.clone());
578	                }
579	                for (_, l) in &imp.named {
580	                    self.import_names.push(l.name.clone());
581	                }
582	            }
583	        }
584	        self.fs.push(FuncState::new(FuncKind::Normal, false, p.has_top_level_await, false, true, rid));
585	        self.enter_scope(rid, true);
586	        self.init_internal_bindings(rid);
587	        self.hoist_functions(&p.body, true)?;
588	        self.emit(Op::ModuleBodyStart);
589	        for s in &p.body {
590	            self.compile_stmt(s)?;
591	        }
592	        self.emit(Op::Undef);
593	        self.emit(Op::Return);
594	        self.exit_scope_noemit();
595	        let fs = self.fs.pop().unwrap();
596	        let mut code = self.finish(fs, JsStr::empty(), 0, 0, 0, 0, true);
597	        code.is_module = true;
598	        let names = self.import_names.clone();
599	        Ok((Rc::new(code), names))
600	    }
