608	    fn init_internal_bindings(&mut self, rid: usize) {
609	        let rs = self.rscope(rid);
610	        for d in &rs.decls {
611	            if d.kind != BindKind::Internal {
612	                continue;
613	            }
614	            let (st, name) = {
615	                let sc = self.f().scopes.last().unwrap();
616	                match sc.names.iter().find(|(n, _, _)| *n == d.name) {
617	                    Some((n, st, _)) => (*st, n.clone()),
618	                    None => continue,
619	                }
620	            };
621	            let op = match &*name {
622	                "this" => Op::This,
623	                "new.target" => Op::NewTarget,
624	                "%home" => Op::Home,
625	                "%func" => Op::Callee,
626	                "arguments" => Op::CreateArguments(false),
627	                _ => continue,
628	            };
629	            // only materialize if captured or used
630	            if &*name == "arguments" && !rs.uses_arguments && !d.captured {
631	                continue;
632	            }
633	            self.emit(op);
634	            match st {
635	                Storage::Local(s) => {
636	                    self.emit(Op::InitLocal(s));
637	                }
638	                Storage::Env(s) => {
639	                    self.emit(Op::InitEnv(0, s));
640	                }
641	            }
642	        }
643	    }
