647	            let t = fs.label_pos[l.0 as usize].expect("unplaced label");
648	            set_target(&mut fs.ops[*i], t);
649	        }
650	        FunctionCode {
651	            name,
652	            ops: fs.ops,
653	            consts: fs.consts,
654	            keys: fs.keys,
655	            funcs: fs.funcs,
656	            scopes: fs.scope_infos,
657	            templates: fs.templates,
658	            regexps: fs.regexps,
659	            strings: fs.strings,
660	            nlocals: fs.nlocals,
661	            length,
662	            kind: fs.kind,
663	            is_async: fs.is_async,
664	            is_generator: fs.is_generator,
665	            strict: fs.strict,
666	            source: self.source.clone(),
667	            src_start,
668	            src_end,
669	            is_arrow: fs.is_arrow,
670	            has_simple_params: simple,
671	            line,
672	            no_prototype: false,
673	            class_source: false,
674	            is_default_ctor: false,
675	            is_script: false,
676	            is_module: false,
677	            is_eval: false,
678	        }
