681	    // ---------- hoisting ----------
682	
683	    fn hoist_functions(&mut self, stmts: &'a [Stmt], _top: bool) -> CResult<()> {
684	        for s in stmts {
685	            let mut s = s;
686	            while let Stmt::Labeled(_, inner) = s {
687	                s = inner;
688	            }
689	            let f = match s {
690	                Stmt::Function(f) => f,
691	                Stmt::Export(e) => match &**e {
692	                    ExportDecl::Decl(Stmt::Function(f)) => f,
693	                    ExportDecl::DefaultFunc(f) => {
694	                        let idx = self.compile_function(f, Some(JsStr::from_str("default")))?;
695	                        self.emit(Op::Closure(idx));
696	                        let name: String = match &f.name {
697	                            Some(n) => n.name.to_string(),
698	                            None => "*default*".to_string(),
699	                        };
700	                        self.init_name(&name);
701	                        continue;
702	                    }
703	                    _ => continue,
704	                },
705	                _ => continue,
706	            };
707	            let name = match &f.name {
708	                Some(n) => n.name.clone(),
709	                None => continue,
710	            };
711	            let idx = self.compile_function(f, None)?;
712	            self.emit(Op::Closure(idx));
713	            match self.resolve(&name) {
714	                Resolved::Global => {
715	                    let k = self.key_idx(&name);
716	                    self.emit(Op::SetGlobal(k));
717	                    self.emit(Op::Pop);
718	                }
719	                _ => self.init_name(&name),
720	            }
721	        }
722	        Ok(())
723	    }
