725	    // ---------- control flow helpers ----------
726	
727	    /// Emit cleanup code for leaving ctl entries above index `to` (exclusive).
728	    fn unwind_to(&mut self, to: usize) -> CResult<()> {
729	        let mut i = self.f().ctl.len();
730	        while i > to {
731	            i -= 1;
732	            match &self.f().ctl[i] {
733	                Ctl::Scope => {
734	                    self.emit(Op::PopScope);
735	                }
736	                Ctl::Try { finalizer, scope_depth } => {
737	                    let fin = *finalizer;
738	                    let depth = *scope_depth;
739	                    self.emit(Op::TryEnd);
740	                    if let Some(b) = fin {
741	                        // compile finally with ctl truncated and the compile-time scope chain as it
742	                        // was at the try statement (runtime envs were popped by PopScope above)
743	                        let saved: Vec<Ctl<'a>> = self.f().ctl.drain(i..).collect();
744	                        let saved_scopes: Vec<CScope> = self.f().scopes.drain(depth..).collect();
745	                        self.compile_block(b)?;
746	                        self.f().scopes.extend(saved_scopes);
747	                        self.f().ctl.extend(saved);
748	                    }
749	                }
750	                Ctl::Iter { is_async } => {
751	                    if *is_async {
752	                        self.emit(Op::IterCloseAsync);
753	                        self.emit(Op::Await);
754	                        self.emit(Op::Pop);
755	                    } else {
756	                        self.emit(Op::IterClose);
757	                    }
758	                }
759	                Ctl::Stack(n) => {
760	                    for _ in 0..*n {
761	                        self.emit(Op::Pop);
762	                    }
763	                }
764	                Ctl::Loop { .. } | Ctl::Breakable { .. } => {}
765	            }
766	        }
767	        Ok(())
768	    }
769	
770	    fn find_break_target(&self, label: Option<&Rc<str>>, is_continue: bool) -> Option<(usize, Label)> {
771	        let ctl = &self.fs.last().unwrap().ctl;
772	        for i in (0..ctl.len()).rev() {
773	            match &ctl[i] {
774	                Ctl::Loop { labels, brk, cont } => match label {
775	                    None => return Some((i, if is_continue { *cont } else { *brk })),
776	                    Some(l) => {
777	                        if labels.contains(l) {
778	                            return Some((i, if is_continue { *cont } else { *brk }));
779	                        }
780	                    }
781	                },
782	                Ctl::Breakable { labels, brk } => {
783	                    if is_continue {
784	                        continue;
785	                    }
786	                    match label {
787	                        None => {
788	                            // unlabeled break targets switch (labels empty and marked) - Breakable with
789	                            // empty label list represents a switch
790	                            if labels.is_empty() {
791	                                return Some((i, *brk));
792	                            }
793	                        }
794	                        Some(l) => {
795	                            if labels.contains(l) {
796	                                return Some((i, *brk));
797	                            }
798	                        }
799	                    }
800	                }
801	                _ => {}
802	            }
803	        }
804	        None
805	    }
