807	    // ---------- statements ----------
808	
809	    fn compile_block(&mut self, b: &'a Block) -> CResult<()> {
810	        let rid = b.scope.get() as usize;
811	        let has_env = self.enter_scope(rid, false);
812	        if has_env {
813	            self.f().ctl.push(Ctl::Scope);
814	        }
815	        self.mark_scope_depth();
816	        self.hoist_functions(&b.body, false)?;
817	        for s in &b.body {
818	            self.compile_stmt(s)?;
819	        }
820	        if has_env {
821	            self.f().ctl.pop();
822	        }
823	        self.exit_scope();
824	        Ok(())
825	    }
826	
827	    fn mark_scope_depth(&mut self) {}
828	
829	    fn take_labels(&mut self) -> Vec<Rc<str>> {
830	        std::mem::take(&mut self.f().pending_labels)
831	    }
832	
833	    fn compile_stmt(&mut self, s: &'a Stmt) -> CResult<()> {
834	        match s {
835	            Stmt::Expr(e) => {
836	                self.compile_expr(e)?;
837	                if let Some(c) = self.f().completion_slot {
838	                    self.emit(Op::SetCompletion(c));
839	                } else {

840	                    self.emit(Op::Pop);
841	                }
842	            }
843	            Stmt::Var(d) => self.compile_var_decl(d)?,
844	            Stmt::Function(f) => {
845	                // annex B: copy block-level function binding to var binding
846	                if let Some(n) = &f.name {
847	                    if !f.strict && !self.f().strict {
848	                        self.annexb_copy(&n.name, f)?;
849	                    }
850	                }
851	            }
852	            Stmt::Class(c) => {
853	                self.compile_class(c, None)?;
854	                let name = c.name.as_ref().unwrap().name.clone();
855	                self.init_name(&name);
856	            }
857	            Stmt::Return(e) => {
858	                match e {
859	                    Some(e) => self.compile_expr(e)?,
860	                    None => {
861	                        self.emit(Op::Undef);
862	                    }
863	                }
864	                self.emit_return()?;
865	            }
866	            Stmt::If(t, a, b) => {
867	                let l_else = self.new_label();
868	                self.compile_cond_jump(t, false, l_else)?;
869	                self.compile_sub_stmt(a)?;
870	                if let Some(b) = b {
871	                    let l_end = self.new_label();
872	                    self.emit_jump(Op::Jump(0), l_end);
873	                    self.place(l_else);
874	                    self.compile_sub_stmt(b)?;
875	                    self.place(l_end);
876	                } else {
877	                    self.place(l_else);
878	                }
879	            }
880	            Stmt::Block(b) => {
881	                let labels = self.take_labels();
882	                if !labels.is_empty() {
883	                    let brk = self.new_label();
884	                    self.f().ctl.push(Ctl::Breakable { labels, brk });
885	                    self.compile_block(b)?;
886	                    self.f().ctl.pop();
887	                    self.place(brk);
888	                } else {
889	                    self.compile_block(b)?;
890	                }
891	            }
892	            Stmt::For(f) => self.compile_for(f)?,
893	            Stmt::ForIn(f) => self.compile_for_in(f)?,
894	            Stmt::ForOf(f) => self.compile_for_of(f)?,
895	            Stmt::While(t, body) => {
896	                let labels = self.take_labels();
897	                let l_top = self.new_label();
898	                let l_end = self.new_label();
899	                self.place(l_top);
900	                self.compile_cond_jump(t, false, l_end)?;
901	                self.f().ctl.push(Ctl::Loop { labels, brk: l_end, cont: l_top });
902	                self.compile_sub_stmt(body)?;
903	                self.f().ctl.pop();
904	                self.emit_jump(Op::Jump(0), l_top);
905	                self.place(l_end);
906	            }
907	            Stmt::DoWhile(body, t) => {
908	                let labels = self.take_labels();
909	                let l_top = self.new_label();
910	                let l_cont = self.new_label();
911	                let l_end = self.new_label();
912	                self.place(l_top);
913	                self.f().ctl.push(Ctl::Loop { labels, brk: l_end, cont: l_cont });
914	                self.compile_sub_stmt(body)?;
915	                self.f().ctl.pop();
916	                self.place(l_cont);
917	                self.compile_cond_jump(t, true, l_top)?;
918	                self.place(l_end);
919	            }
920	            Stmt::Break(label) => {
921	                let (idx, target) = match self.find_break_target(label.as_ref(), false) {
922	                    Some(x) => x,
923	                    None => return cerr("illegal 'break' statement", 0),
924	                };
925	                self.unwind_to(idx + 1)?;
926	                self.emit_jump(Op::Jump(0), target);
927	            }
928	            Stmt::Continue(label) => {
929	                let (idx, target) = match self.find_break_target(label.as_ref(), true) {
930	                    Some(x) => x,
931	                    None => return cerr("illegal 'continue' statement", 0),
932	                };
933	                self.unwind_to(idx + 1)?;
934	                self.emit_jump(Op::Jump(0), target);
935	            }
936	            Stmt::Throw(e) => {
937	                self.compile_expr(e)?;
938	                self.emit(Op::Throw);
939	            }
940	            Stmt::Try(t) => self.compile_try(t)?,
941	            Stmt::Switch(sw) => self.compile_switch(sw)?,
942	            Stmt::Labeled(l, body) => {
943	                self.f().pending_labels.push(l.clone());
944	                match &**body {
945	                    Stmt::For(_) | Stmt::ForIn(_) | Stmt::ForOf(_) | Stmt::While(..) | Stmt::DoWhile(..) | Stmt::Labeled(..) | Stmt::Block(_) => {
946	                        self.compile_stmt(body)?;
947	                    }
948	                    _ => {
949	                        let labels = self.take_labels();
950	                        let brk = self.new_label();
951	                        self.f().ctl.push(Ctl::Breakable { labels, brk });
952	                        self.compile_stmt(body)?;
953	                        self.f().ctl.pop();
954	                        self.place(brk);
955	                    }
956	                }
957	            }
958	            Stmt::Empty | Stmt::Debugger => {}
959	            Stmt::With(obj, body, sid) => {
960	                self.compile_expr(obj)?;
961	                self.emit(Op::PushWith);
962	                let rid = sid.get() as usize;
963	                self.f().scopes.push(CScope { rid, has_env: true, names: Vec::new(), is_with: true, dyn_eval: false });
964	                self.f().ctl.push(Ctl::Scope);
965	                self.compile_sub_stmt(body)?;
966	                self.f().ctl.pop();
967	                self.exit_scope();
968	            }
969	            Stmt::Import(_) => {}
970	            Stmt::Export(e) => self.compile_export(e)?,
971	        }
972	        Ok(())
973	    }
