975	    fn annexb_copy(&mut self, name: &Rc<str>, _f: &'a Function) -> CResult<()> {
976	        // if the name resolves (innermost) to a block-level function binding and the function
977	        // scope has a var binding with the same name, copy it
978	        let fs = self.fs.last().unwrap();
979	        let n = fs.scopes.len();
980	        if n == 0 {
981	            return Ok(());
982	        }
983	        // find innermost scope declaring name
984	        let mut inner_idx = None;
985	        for i in (0..n).rev() {
986	            if fs.scopes[i].names.iter().any(|(x, _, _)| x == name) {
987	                inner_idx = Some(i);
988	                break;
989	            }
990	        }
991	        let inner_idx = match inner_idx {
992	            Some(i) => i,
993	            None => {
994	                // top-level script function or sub-statement function: assign to var binding
995	                return self.annexb_assign_sub(name, _f);
996	            }
997	        };
998	        let rid = fs.scopes[inner_idx].rid;
999	        if is_function_like(self.rscope(rid).kind) {
1000	            // declared at function level already (not a block function)
1001	            if !self.is_hoisted_in(inner_idx, name) {
1002	                return self.annexb_assign_sub(name, _f);
1003	            }
1004	            return Ok(());
1005	        }
1006	        // find function-level var binding
1007	        let mut func_idx = None;
1008	        for i in (0..inner_idx).rev() {
1009	            let k = self.rscope(fs.scopes[i].rid).kind;
1010	            if is_function_like(k) {
1011	                func_idx = Some(i);
1012	                break;
1013	            }
1014	        }
1015	        // value from block binding
1016	        self.load_name(name);
1017	        match func_idx {
1018	            Some(fi) => {
1019	                let st = fs_find(&self.fs.last().unwrap().scopes[fi], name);
1020	                match st {
1021	                    Some((Storage::Local(s), BindKind::Var | BindKind::Function)) => {
1022	                        self.emit(Op::SetLocal(s));
1023	                    }
1024	                    Some((Storage::Env(s), BindKind::Var | BindKind::Function)) => {
1025	                        // compute depth from current position to scope fi
1026	                        let mut depth = 0u16;
1027	                        let fsr = self.fs.last().unwrap();
1028	                        for j in ((fi + 1)..fsr.scopes.len()).rev() {
1029	                            if fsr.scopes[j].has_env {
1030	                                depth += 1;
1031	                            }
1032	                        }
1033	                        self.emit(Op::SetEnv(depth, s));
1034	                    }
1035	                    _ => {
1036	                        let rk = self.rscope(self.fs.last().unwrap().scopes[fi].rid).kind;
1037	                        if rk == ScopeKind::Script || (rk == ScopeKind::Eval) {
1038	                            let k = self.key_idx(name);
1039	                            if rk == ScopeKind::Script {
1040	                                self.emit(Op::SetGlobal(k));
1041	                            } else {
1042	                                self.emit(Op::SetName(k));
1043	                            }
1044	                        }
1045	                    }
1046	                }
1047	            }
1048	            None => {}
1049	        }
1050	        self.emit(Op::Pop);
1051	        Ok(())
1052	    }
1053	
1054	    fn is_hoisted_in(&self, _idx: usize, _name: &str) -> bool {
1055	        true
1056	    }
1057	
1058	    /// function declaration not hoisted by an enclosing block (e.g. `if (x) function f(){}`)
1059	    fn annexb_assign_sub(&mut self, name: &Rc<str>, f: &'a Function) -> CResult<()> {
1060	        let _ = (name, f);
1061	        Ok(())
1062	    }
1063	
1064	    fn compile_sub_stmt(&mut self, s: &'a Stmt) -> CResult<()> {
1065	        if let Stmt::Function(f) = s {
1066	            // function declaration as substatement: evaluate and assign
1067	            let idx = self.compile_function(f, None)?;
1068	            self.emit(Op::Closure(idx));
1069	            let name = f.name.as_ref().unwrap().name.clone();
1070	            match self.resolve(&name) {
1071	                Resolved::Global => {
1072	                    let k = self.key_idx(&name);
1073	                    self.emit(Op::SetGlobal(k));
1074	                }
1075	                _ => {
1076	                    self.store_name(&name, 0)?;
1077	                }
1078	            }
1079	            self.emit(Op::Pop);
1080	            return Ok(());
1081	        }
1082	        self.compile_stmt(s)
1083	    }
1084	
1085	    fn emit_return(&mut self) -> CResult<()> {
1086	        if self.f().kind == FuncKind::DerivedConstructor {
1087	            // undefined -> this (with TDZ check)
1088	            let l = self.new_label();
1089	            self.emit(Op::Dup);
1090	            self.emit_jump(Op::JumpIfNotUndef(0), l);
1091	            self.emit(Op::Pop);
1092	            self.load_this();
1093	            self.place(l);
1094	        }
1095	        let needs_cleanup = self.f().ctl.iter().any(|c| matches!(c, Ctl::Try { .. } | Ctl::Iter { .. }));
1096	        if needs_cleanup {
1097	            let slot = self.ret_slot();
1098	            self.emit(Op::SetLocal(slot));
1099	            self.emit(Op::Pop);
1100	            self.unwind_to(0)?;
1101	            self.emit(Op::GetLocal(slot));
1102	        }
1103	        self.emit(Op::Return);
1104	        Ok(())
1105	    }
1106	
1107	    fn ret_slot(&mut self) -> u32 {
1108	        if let Some(s) = self.f().ret_slot {
1109	            return s;
1110	        }
1111	        let s = self.new_local();
1112	        self.f().ret_slot = Some(s);
1113	        s
1114	    }
1115	
1116	    fn compile_var_decl(&mut self, d: &'a VarDecl) -> CResult<()> {
1117	        for decl in &d.decls {
1118	            match &decl.init {
1119	                Some(init) => {
1120	                    let hint = match &decl.target {
1121	                        Pattern::Ident(id) if init.is_anonymous_fn() => Some(JsStr::from_str(&id.name)),
1122	                        _ => None,
1123	                    };
1124	                    self.compile_expr_named(init, hint)?;
1125	                    if matches!(d.kind, VarKind::Using | VarKind::AwaitUsing) {
1126	                        self.emit(Op::AddDisposable(d.kind == VarKind::AwaitUsing));
1127	                    }
1128	                    self.compile_binding(&decl.target, d.kind)?;
1129	                }
1130	                None => {
1131	                    if d.kind == VarKind::Var {
1132	                        continue;
1133	                    }
1134	                    self.emit(Op::Undef);
1135	                    self.compile_binding(&decl.target, d.kind)?;
1136	                }
1137	            }
1138	        }
1139	        Ok(())
1140	    }
