1142	    /// Bind value on stack to pattern (declaration). Consumes the value.
1143	    fn compile_binding(&mut self, p: &'a Pattern, kind: VarKind) -> CResult<()> {
1144	        match p {
1145	            Pattern::Ident(id) => {
1146	                if kind == VarKind::Var {
1147	                    match self.resolve(&id.name) {
1148	                        Resolved::Global => {
1149	                            let k = self.key_idx(&id.name);
1150	                            self.emit(Op::SetGlobal(k));
1151	                            self.emit(Op::Pop);
1152	                        }
1153	                        _ => {
1154	                            self.store_name(&id.name, id.line)?;
1155	                            self.emit(Op::Pop);
1156	                        }
1157	                    }
1158	                } else {
1159	                    self.init_name(&id.name);
1160	                }
1161	                Ok(())
1162	            }
1163	            _ => self.compile_pattern(p, Some(kind)),
1164	        }
1165	    }
1166	
1167	    /// Destructure value on stack into pattern. kind None = assignment pattern. Consumes value.
1168	    fn compile_pattern(&mut self, p: &'a Pattern, kind: Option<VarKind>) -> CResult<()> {
1169	        match p {
1170	            Pattern::Ident(id) => match kind {
1171	                Some(k) => self.compile_binding(p, k),
1172	                None => {
1173	                    self.store_name(&id.name, id.line)?;
1174	                    self.emit(Op::Pop);
1175	                    Ok(())
1176	                }
1177	            },
1178	            Pattern::Expr(e) => {
1179	                // assignment target expression; value on stack
1180	                self.compile_store_to_expr(e)?;
1181	                self.emit(Op::Pop);
1182	                Ok(())
1183	            }
1184	            Pattern::Object { props, rest } => {
1185	                self.emit(Op::RequireObjCoercible);
1186	                let mut computed_keys: Vec<u32> = Vec::new();
1187	                for prop in props {
1188	                    self.emit(Op::Dup);
1189	                    match &prop.key {
1190	                        PropKey::Computed(e) => {
1191	                            self.compile_expr(e)?;
1192	                            self.emit(Op::ToPropKey);
1193	                            if rest.is_some() {
1194	                                let t = self.new_local();
1195	                                self.emit(Op::SetLocal(t));
1196	                                computed_keys.push(t);
1197	                            }
1198	                            self.emit(Op::GetElem);
1199	                        }
1200	                        PropKey::Private(_) => return cerr("unexpected private name in pattern", 0),
1201	                        k => {
1202	                            let name = propkey_static_name(k).unwrap();
1203	                            let ki = match k {
1204	                                PropKey::Str(u) => self.key_idx_units(u),
1205	                                _ => self.key_idx(&name),
1206	                            };
1207	                            self.emit(Op::GetProp(ki));
1208	                        }
1209	                    }
1210	                    if let Some(d) = &prop.default {
1211	                        let l = self.new_label();
1212	                        self.emit(Op::Dup);
1213	                        self.emit_jump(Op::JumpIfNotUndef(0), l);
1214	                        self.emit(Op::Pop);
1215	                        let hint = match &prop.target {
1216	                            Pattern::Ident(id) if d.is_anonymous_fn() => Some(JsStr::from_str(&id.name)),
1217	                            _ => None,
1218	                        };
1219	                        self.compile_expr_named(d, hint)?;
1220	                        self.place(l);
1221	                    }
1222	                    self.compile_pattern(&prop.target, kind)?;
1223	                }
1224	                if let Some(r) = rest {
1225	                    // excluded keys
1226	                    let mut n = 0u32;
1227	                    let mut ci = 0;
1228	                    for prop in props {
1229	                        match &prop.key {
1230	                            PropKey::Computed(_) => {
1231	                                self.emit(Op::GetLocal(computed_keys[ci]));
1232	                                ci += 1;
1233	                            }
1234	                            k => {
1235	                                let name = propkey_static_name(k).unwrap();
1236	                                self.push_str(&units(&name));
1237	                            }
1238	                        }
1239	                        n += 1;
1240	                    }
1241	                    self.emit(Op::CopyDataPropsExcept(n));
1242	                    self.compile_pattern(r, kind)?;
1243	                } else {
1244	                    self.emit(Op::Pop);
1245	                }
1246	                Ok(())
1247	            }
1248	            Pattern::Array { elems, rest } => {
1249	                self.emit(Op::DestructIter);
1250	                // [iter next done]
1251	                let try_label = self.new_label();
1252	                let end_label = self.new_label();
1253	                self.emit_jump(Op::TryStart(0), try_label);
1254	                for el in elems {
1255	                    match el {
1256	                        None => {
1257	                            self.emit(Op::IterValue);
1258	                            self.emit(Op::Pop);
1259	                        }
1260	                        Some(el) => {
1261	                            // assignment targets: evaluate reference first (simplified: after value)
1262	                            self.emit(Op::IterValue);
1263	                            if let Some(d) = &el.default {
1264	                                let l = self.new_label();
1265	                                self.emit(Op::Dup);
1266	                                self.emit_jump(Op::JumpIfNotUndef(0), l);
1267	                                self.emit(Op::Pop);
1268	                                let hint = match &el.target {
1269	                                    Pattern::Ident(id) if d.is_anonymous_fn() => Some(JsStr::from_str(&id.name)),
1270	                                    _ => None,
1271	                                };
1272	                                self.compile_expr_named(d, hint)?;
1273	                                self.place(l);
1274	                            }
1275	                            self.compile_pattern(&el.target, kind)?;
1276	                        }
1277	                    }
1278	                }
1279	                if let Some(r) = rest {
1280	                    self.emit(Op::IterRest);
1281	                    self.compile_pattern(r, kind)?;
1282	                }
1283	                self.emit(Op::TryEnd);
1284	                self.emit(Op::IterDone);
1285	                self.emit_jump(Op::Jump(0), end_label);
1286	                // exception during destructuring: close iterator (if not done) and rethrow
1287	                self.place(try_label);
1288	                // stack: [iter next done exc]
1289	                self.emit(Op::Rot4);
1290	                // [exc iter next done]
1291	                self.emit(Op::IterCloseThrow);
1292	                self.place(end_label);
1293	                Ok(())
1294	            }
1295	        }
1296	    }
