1298	    /// store value on stack into member expression target (value remains)
1299	    fn compile_store_to_expr(&mut self, e: &'a Expr) -> CResult<()> {
1300	        match e.unparen() {
1301	            Expr::Ident(id) => {
1302	                self.store_name(&id.name, id.line)?;
1303	            }
1304	            Expr::Member { obj, prop, .. } => {
1305	                self.compile_expr(obj)?;
1306	                match prop {
1307	                    MemberProp::Name(n) => {
1308	                        self.emit(Op::Swap);
1309	                        let k = self.key_idx(n);
1310	                        self.emit(Op::SetProp(k));
1311	                    }
1312	                    MemberProp::Computed(k) => {
1313	                        self.compile_expr(k)?;
1314	                        self.emit(Op::Rot3);
1315	                        self.emit(Op::SetElem);
1316	                    }
1317	                    MemberProp::Private(n) => {
1318	                        self.load_name(&format!("#{}", n));
1319	                        self.emit(Op::Rot3);
1320	                        self.emit(Op::SetPrivate);
1321	                    }
1322	                }
1323	            }
1324	            Expr::SuperMember(prop) => {
1325	                self.emit(Op::ThisChk);
1326	                match prop {
1327	                    MemberProp::Name(n) => {
1328	                        self.emit(Op::Swap);
1329	                        let k = self.key_idx(n);
1330	                        self.emit(Op::SetSuper(k));
1331	                    }
1332	                    MemberProp::Computed(k) => {
1333	                        self.compile_expr(k)?;
1334	                        self.emit(Op::ToPropKey);
1335	                        self.emit(Op::Rot3);
1336	                        self.emit(Op::SetSuperElem);
1337	                    }
1338	                    MemberProp::Private(_) => return cerr("unexpected private", 0),
1339	                }
1340	            }
1341	            _ => return cerr("invalid assignment target", 0),
1342	        }
1343	        Ok(())
1344	    }
