1346	    fn compile_for(&mut self, f: &'a ForStmt) -> CResult<()> {
1347	        let labels = self.take_labels();
1348	        let rid = f.scope.get() as usize;
1349	        let has_env = self.enter_scope(rid, false);
1350	        if has_env {
1351	            self.f().ctl.push(Ctl::Scope);
1352	        }
1353	        let per_iter = has_env
1354	            && matches!(&f.init, Some(ForInit::Var(d)) if d.kind == VarKind::Let || d.kind == VarKind::Const);
1355	        if let Some(init) = &f.init {
1356	            match init {
1357	                ForInit::Var(d) => self.compile_var_decl(d)?,
1358	                ForInit::Expr(e) => {
1359	                    self.compile_expr(e)?;
1360	                    self.emit(Op::Pop);
1361	                }
1362	            }
1363	        }
1364	        if per_iter {
1365	            self.emit(Op::CopyScope);
1366	        }
1367	        let l_top = self.new_label();
1368	        let l_cont = self.new_label();
1369	        let l_end = self.new_label();
1370	        self.place(l_top);
1371	        if let Some(t) = &f.test {
1372	            self.compile_cond_jump(t, false, l_end)?;
1373	        }
1374	        self.f().ctl.push(Ctl::Loop { labels, brk: l_end, cont: l_cont });
1375	        self.compile_sub_stmt(&f.body)?;
1376	        self.f().ctl.pop();
1377	        self.place(l_cont);
1378	        if per_iter {
1379	            self.emit(Op::CopyScope);
1380	        }
1381	        if let Some(u) = &f.update {
1382	            self.compile_expr(u)?;
1383	            self.emit(Op::Pop);
1384	        }
1385	        self.emit_jump(Op::Jump(0), l_top);
1386	        self.place(l_end);
1387	        if has_env {
1388	            self.f().ctl.pop();
1389	        }
1390	        self.exit_scope();
1391	        Ok(())
1392	    }
