1394	    /// bind the iteration value (on stack) for for-in/of heads
1395	    fn compile_for_head_binding(&mut self, head: &'a ForHead) -> CResult<()> {
1396	        match head {
1397	            ForHead::Decl(kind, p) => self.compile_binding(p, *kind),
1398	            ForHead::Target(p) => self.compile_pattern(p, None),
1399	        }

1400	    }
