1402	    fn compile_for_in(&mut self, f: &'a ForInOf) -> CResult<()> {
1403	        let labels = self.take_labels();
1404	        let rid = f.scope.get() as usize;
1405	        // legacy initializer: for (var x = init in obj)
1406	        if let Some(vi) = &f.var_init {
1407	            if let ForHead::Decl(_, Pattern::Ident(id)) = &f.head {
1408	                self.compile_expr(vi)?;
1409	                match self.resolve(&id.name) {
1410	                    Resolved::Global => {
1411	                        let k = self.key_idx(&id.name);
1412	                        self.emit(Op::SetGlobal(k));
1413	                    }
1414	                    _ => {
1415	                        self.store_name(&id.name, id.line)?;
1416	                    }
1417	                }
1418	                self.emit(Op::Pop);
1419	            }
1420	        }
1421	        // evaluate the object in a TDZ scope for the loop bindings
1422	        let has_env = self.enter_scope(rid, false);
1423	        self.compile_expr(&f.right)?;
1424	        if has_env {
1425	            self.emit(Op::PopScope);
1426	        }
1427	        self.f().scopes.pop();
1428	        self.emit(Op::ForInStart);
1429	        self.f().ctl.push(Ctl::Stack(1));
1430	        let l_top = self.new_label();
1431	        let l_end = self.new_label();
1432	        let l_exit = self.new_label();
1433	        self.place(l_top);
1434	        self.emit_jump(Op::ForInNext(0), l_end);
1435	        // per-iteration scope
1436	        let has_env2 = self.enter_scope(rid, false);
1437	        if has_env2 {
1438	            self.f().ctl.push(Ctl::Scope);
1439	        }
1440	        self.compile_for_head_binding(&f.head)?;
1441	        let l_cont = self.new_label();
1442	        self.f().ctl.push(Ctl::Loop { labels, brk: l_exit, cont: l_cont });
1443	        self.compile_sub_stmt(&f.body)?;
1444	        self.f().ctl.pop();
1445	        self.place(l_cont);
1446	        if has_env2 {
1447	            self.f().ctl.pop();
1448	        }
1449	        self.exit_scope();
1450	        self.emit_jump(Op::Jump(0), l_top);
1451	        // fix: continue must pop scope before jumping to top; handled since cont label is before exit_scope
1452	        self.place(l_exit);
1453	        self.place(l_end);
1454	        self.f().ctl.pop();
1455	        self.emit(Op::Pop);
1456	        Ok(())
1457	    }
