1459	    fn compile_for_of(&mut self, f: &'a ForInOf) -> CResult<()> {
1460	        let labels = self.take_labels();
1461	        let rid = f.scope.get() as usize;
1462	        let has_env = self.enter_scope(rid, false);
1463	        self.compile_expr(&f.right)?;
1464	        if has_env {
1465	            self.emit(Op::PopScope);
1466	        }
1467	        self.f().scopes.pop();
1468	        if f.is_await {
1469	            self.emit(Op::GetAsyncIterator);
1470	        } else {
1471	            self.emit(Op::GetIterator);
1472	        }
1473	        // [iter next]
1474	        self.f().ctl.push(Ctl::Iter { is_async: f.is_await });
1475	        let l_top = self.new_label();
1476	        let l_done = self.new_label();
1477	        let l_brk = self.new_label();
1478	        let l_exc = self.new_label();
1479	        let l_end = self.new_label();
1480	        self.place(l_top);
1481	        if f.is_await {
1482	            self.emit(Op::IterCallNext);
1483	            self.emit(Op::Await);
1484	            self.emit_jump(Op::AsyncIterCheck(0), l_done);
1485	        } else {
1486	            self.emit_jump(Op::IterNext(0), l_done);
1487	        }
1488	        // [iter next value]
1489	        self.f().ctl.push(Ctl::Loop { labels, brk: l_brk, cont: l_top });
1490	        self.emit_jump(Op::TryStart(0), l_exc);
1491	        { let d = self.f().scopes.len(); self.f().ctl.push(Ctl::Try { finalizer: None, scope_depth: d }); }
1492	        let has_env2 = self.enter_scope(rid, false);
1493	        if has_env2 {
1494	            self.f().ctl.push(Ctl::Scope);
1495	        }
1496	        self.compile_for_head_binding(&f.head)?;
1497	        self.compile_sub_stmt(&f.body)?;
1498	        if has_env2 {
1499	            self.f().ctl.pop();
1500	        }
1501	        self.exit_scope();
1502	        self.f().ctl.pop(); // Try
1503	        self.emit(Op::TryEnd);
1504	        self.f().ctl.pop(); // Loop
1505	        self.emit_jump(Op::Jump(0), l_top);
1506	        // exception in body: [iter next exc]
1507	        self.place(l_exc);
1508	        if f.is_await {
1509	            // async close: call return, await, ignore result; rethrow
1510	            self.emit(Op::Rot3);
1511	            // [exc iter next]
1512	            self.emit(Op::IterCloseAsync);
1513	            self.emit(Op::Await);
1514	            self.emit(Op::Pop);
1515	            self.emit(Op::Throw);
1516	        } else {
1517	            self.emit(Op::Rot3);
1518	            self.emit(Op::IterCloseThrow);
1519	        }
1520	        // break
1521	        self.place(l_brk);
1522	        self.f().ctl.pop(); // Iter
1523	        if f.is_await {
1524	            self.emit(Op::IterCloseAsync);
1525	            self.emit(Op::Await);
1526	            self.emit(Op::Pop);
1527	        } else {
1528	            self.emit(Op::IterClose);
1529	        }
1530	        self.emit_jump(Op::Jump(0), l_end);
1531	        self.place(l_done);
1532	        self.emit(Op::Pop);
1533	        self.emit(Op::Pop);
1534	        self.place(l_end);
1535	        Ok(())
1536	    }
