1538	    fn compile_try(&mut self, t: &'a TryStmt) -> CResult<()> {
1539	        let l_catch = self.new_label();
1540	        let l_end = self.new_label();
1541	        let has_finally = t.finalizer.is_some();
1542	        let l_finally_exc = self.new_label();
1543	        if has_finally {
1544	            // outer handler for finally (covers try + catch)
1545	            self.emit_jump(Op::TryStart(0), l_finally_exc);
1546	            let d = self.f().scopes.len();
1547	            self.f().ctl.push(Ctl::Try { finalizer: t.finalizer.as_ref(), scope_depth: d });
1548	        }
1549	        if t.handler.is_some() {
1550	            self.emit_jump(Op::TryStart(0), l_catch);
1551	            let d = self.f().scopes.len();
1552	            self.f().ctl.push(Ctl::Try { finalizer: None, scope_depth: d });
1553	        }
1554	        self.compile_block(&t.block)?;
1555	        if t.handler.is_some() {
1556	            self.f().ctl.pop();
1557	            self.emit(Op::TryEnd);
1558	        }
1559	        let l_after_catch = self.new_label();
1560	        self.emit_jump(Op::Jump(0), l_after_catch);
1561	        if let Some(h) = &t.handler {
1562	            self.place(l_catch);
1563	            // exception on stack
1564	            let rid = t.catch_scope.get() as usize;
1565	            let has_env = self.enter_scope(rid, false);
1566	            if has_env {
1567	                self.f().ctl.push(Ctl::Scope);
1568	            }
1569	            match &t.param {
1570	                Some(p) => self.compile_binding(p, VarKind::Let)?,
1571	                None => {
1572	                    self.emit(Op::Pop);
1573	                }
1574	            }
1575	            self.compile_block(h)?;
1576	            if has_env {
1577	                self.f().ctl.pop();
1578	            }
1579	            self.exit_scope();
1580	        }
1581	        self.place(l_after_catch);
1582	        if has_finally {
1583	            self.f().ctl.pop();
1584	            self.emit(Op::TryEnd);
1585	            // normal path finally
1586	            self.compile_block(t.finalizer.as_ref().unwrap())?;
1587	            self.emit_jump(Op::Jump(0), l_end);
1588	            // exception path: [exc]
1589	            self.place(l_finally_exc);
1590	            let slot = self.new_local();
1591	            self.emit(Op::SetLocal(slot));
1592	            self.emit(Op::Pop);
1593	            self.compile_block(t.finalizer.as_ref().unwrap())?;
1594	            self.emit(Op::GetLocal(slot));
1595	            self.emit(Op::Throw);
1596	        }
1597	        self.place(l_end);
1598	        Ok(())
1599	    }
