1601	    fn compile_switch(&mut self, sw: &'a SwitchStmt) -> CResult<()> {
1602	        let labels = self.take_labels();
1603	        self.compile_expr(&sw.disc)?;
1604	        let tmp = self.new_local();
1605	        self.emit(Op::SetLocal(tmp));
1606	        self.emit(Op::Pop);
1607	        let rid = sw.scope.get() as usize;
1608	        let has_env = self.enter_scope(rid, false);
1609	        if has_env {
1610	            self.f().ctl.push(Ctl::Scope);
1611	        }
1612	        // hoist functions in all cases
1613	        for c in &sw.cases {
1614	            self.hoist_functions(&c.body, false)?;
1615	        }
1616	        let l_end = self.new_label();
1617	        let case_labels: Vec<Label> = sw.cases.iter().map(|_| self.new_label()).collect();
1618	        let mut default_idx = None;
1619	        for (i, c) in sw.cases.iter().enumerate() {
1620	            match &c.test {
1621	                Some(t) => {
1622	                    self.emit(Op::GetLocal(tmp));
1623	                    self.compile_expr(t)?;
1624	                    self.emit(Op::StrictEq);
1625	                    self.emit_jump(Op::JumpIfTrue(0), case_labels[i]);
1626	                }
1627	                None => default_idx = Some(i),
1628	            }
1629	        }
1630	        match default_idx {
1631	            Some(i) => {
1632	                self.emit_jump(Op::Jump(0), case_labels[i]);
1633	            }
1634	            None => {
1635	                self.emit_jump(Op::Jump(0), l_end);
1636	            }
1637	        }
1638	        let mut labels = labels;
1639	        if labels.is_empty() {
1640	            // unlabeled: marker (empty list) means switch
1641	        } else {
1642	            // labeled switch also handles unlabeled breaks: push two entries
1643	        }
1644	        let labeled = !labels.is_empty();
1645	        if labeled {
1646	            self.f().ctl.push(Ctl::Breakable { labels: std::mem::take(&mut labels), brk: l_end });
1647	        }
1648	        self.f().ctl.push(Ctl::Breakable { labels: Vec::new(), brk: l_end });
1649	        for (i, c) in sw.cases.iter().enumerate() {
1650	            self.place(case_labels[i]);
1651	            for s in &c.body {
1652	                self.compile_stmt(s)?;
1653	            }
1654	        }
1655	        self.f().ctl.pop();
1656	        if labeled {
1657	            self.f().ctl.pop();
1658	        }
1659	        self.place(l_end);
1660	        if has_env {
1661	            self.f().ctl.pop();
1662	        }
1663	        self.exit_scope();
1664	        Ok(())
1665	    }
