1667	    fn compile_export(&mut self, e: &'a ExportDecl) -> CResult<()> {
1668	        match e {
1669	            ExportDecl::Decl(s) => self.compile_stmt(s),
1670	            ExportDecl::DefaultExpr(e) => {
1671	                let hint = if e.is_anonymous_fn() { Some(JsStr::from_str("default")) } else { None };
1672	                self.compile_expr_named(e, hint)?;
1673	                self.init_name("*default*");
1674	                Ok(())
1675	            }
1676	            ExportDecl::DefaultFunc(_) => Ok(()),
1677	            ExportDecl::DefaultClass(c) => {
1678	                self.compile_class(c, Some(JsStr::from_str("default")))?;
1679	                let name: String = match &c.name {
1680	                    Some(n) => n.name.to_string(),
1681	                    None => "*default*".to_string(),
1682	                };
1683	                self.init_name(&name);
1684	                Ok(())
1685	            }
1686	            _ => Ok(()),
1687	        }
1688	    }
1689	
1690	    // ---------- conditions ----------
1691	
1692	    /// compile expression and jump to `target` if its truthiness equals `jump_if`
1693	    fn compile_cond_jump(&mut self, e: &'a Expr, jump_if: bool, target: Label) -> CResult<()> {
1694	        match e {
1695	            Expr::Unary(UnaryOp::Not, inner) => return self.compile_cond_jump(inner, !jump_if, target),
1696	            Expr::Logical(LogicalOp::And, a, b) => {
1697	                if jump_if {
1698	                    let skip = self.new_label();
1699	                    self.compile_cond_jump(a, false, skip)?;
1700	                    self.compile_cond_jump(b, true, target)?;
1701	                    self.place(skip);
1702	                } else {
1703	                    self.compile_cond_jump(a, false, target)?;
1704	                    self.compile_cond_jump(b, false, target)?;
1705	                }
1706	                return Ok(());
1707	            }
1708	            Expr::Logical(LogicalOp::Or, a, b) => {
1709	                if jump_if {
1710	                    self.compile_cond_jump(a, true, target)?;
1711	                    self.compile_cond_jump(b, true, target)?;
1712	                } else {
1713	                    let skip = self.new_label();
1714	                    self.compile_cond_jump(a, true, skip)?;
1715	                    self.compile_cond_jump(b, false, target)?;
1716	                    self.place(skip);
1717	                }
1718	                return Ok(());
1719	            }
1720	            Expr::Paren(inner) => return self.compile_cond_jump(inner, jump_if, target),
1721	            _ => {}
1722	        }
1723	        self.compile_expr(e)?;
1724	        if jump_if {
1725	            self.emit_jump(Op::JumpIfTrue(0), target);
1726	        } else {
1727	            self.emit_jump(Op::JumpIfFalse(0), target);
1728	        }
1729	        Ok(())
1730	    }
1731	
1732	    // ---------- expressions ----------
1733	
1734	    fn compile_expr_named(&mut self, e: &'a Expr, name: Option<JsStr>) -> CResult<()> {
1735	        match (e, name) {
1736	            (Expr::Function(f), Some(n)) if f.name.is_none() => {
1737	                let idx = self.compile_function(f, Some(n))?;
1738	                self.emit(Op::Closure(idx));
1739	                Ok(())
1740	            }
1741	            (Expr::Arrow(f), Some(n)) => {
1742	                let idx = self.compile_function(f, Some(n))?;
1743	                self.emit(Op::Closure(idx));
1744	                Ok(())
1745	            }
1746	            (Expr::Class(c), Some(n)) if c.name.is_none() => self.compile_class(c, Some(n)),
1747	            (Expr::Paren(inner), Some(n)) if inner.is_anonymous_fn() => self.compile_expr_named(inner, Some(n)),
1748	            (e, _) => self.compile_expr(e),
1749	        }
1750	    }
1751	
1752	    pub fn compile_expr(&mut self, e: &'a Expr) -> CResult<()> {
1753	        match e {
1754	            Expr::Num(n) => self.push_num(*n),
1755	            Expr::Str(s) => self.push_str(s),
1756	            Expr::BigInt(s) => {
1757	                let b = parse_bigint_literal(s);
1758	                let i = self.const_idx(Value::BigInt(Rc::new(b)));
1759	                self.emit(Op::Const(i));
1760	            }
1761	            Expr::Regex { pattern, flags } => {
1762	                let f = self.f();
1763	                f.regexps.push((JsStr::from_slice(pattern), JsStr::from_slice(flags)));
1764	                let i = (f.regexps.len() - 1) as u32;
1765	                self.emit(Op::RegExp(i));
1766	            }
1767	            Expr::Template { quasis, exprs } => {
1768	                // concatenation with ToString
1769	                let first = quasis[0].cooked.as_ref().unwrap();
1770	                self.push_str(first);
1771	                for (i, ex) in exprs.iter().enumerate() {
1772	                    self.compile_expr(ex)?;
1773	                    self.emit(Op::ToStr);
1774	                    self.emit(Op::Add);
1775	                    let q = quasis[i + 1].cooked.as_ref().unwrap();
1776	                    if !q.is_empty() {
1777	                        self.push_str(q);
1778	                        self.emit(Op::Add);
1779	                    }
1780	                }
1781	            }
1782	            Expr::TaggedTemplate { tag, quasis, exprs, id } => {
1783	                self.compile_callee(tag)?;
1784	                let td = TemplateData {
1785	                    cooked: quasis.iter().map(|q| q.cooked.as_ref().map(|c| JsStr::from_slice(c))).collect(),
1786	                    raw: quasis.iter().map(|q| JsStr::from_slice(&q.raw)).collect(),
1787	                    id: *id,
1788	                };
1789	                let f = self.f();
1790	                f.templates.push(Rc::new(td));
1791	                let ti = (f.templates.len() - 1) as u32;
1792	                self.emit(Op::Template(ti));
1793	                for ex in exprs {
1794	                    self.compile_expr(ex)?;
1795	                }
1796	                let desc = match tag.unparen() {
1797	                    Expr::Ident(id) => self.string_idx(&id.name),
1798	                    _ => self.string_idx("tag"),
1799	                };
1800	                self.emit(Op::Call(exprs.len() as u32 + 1, desc));
1801	            }
1802	            Expr::Bool(true) => {
1803	                self.emit(Op::True);
1804	            }
1805	            Expr::Bool(false) => {
1806	                self.emit(Op::False);
1807	            }
1808	            Expr::Null => {
1809	                self.emit(Op::Null);
1810	            }
1811	            Expr::Ident(id) => {
1812	                if &*id.name == "undefined" {
1813	                    if let Resolved::Global = self.resolve("undefined") {
1814	                        self.emit(Op::Undef);
1815	                        return Ok(());
1816	                    }
1817	                }
1818	                if &*id.name == "arguments" {
1819	                    self.load_arguments();
1820	                    return Ok(());
1821	                }
1822	                self.load_name(&id.name);
1823	            }
1824	            Expr::This => self.load_this(),
1825	            Expr::NewTarget => {
1826	                match self.resolve("new.target") {
1827	                    Resolved::Env(d, s, _) => {
1828	                        self.emit(Op::GetEnv(d, s));
1829	                    }
1830	                    _ => {
1831	                        self.emit(Op::NewTarget);
1832	                    }
1833	                }
1834	            }
1835	            Expr::ImportMeta => {
1836	                self.emit(Op::ImportMeta);
1837	            }
1838	            Expr::SuperMember(prop) => {
1839	                self.load_this();
1840	                match prop {
1841	                    MemberProp::Name(n) => {
1842	                        let k = self.key_idx(n);
1843	                        self.emit(Op::GetSuper(k));
1844	                    }
1845	                    MemberProp::Computed(k) => {
1846	                        self.compile_expr(k)?;
1847	                        self.emit(Op::ToPropKey);
1848	                        self.emit(Op::GetSuperElem);
1849	                    }
1850	                    MemberProp::Private(_) => return cerr("unexpected private", 0),
1851	                }
1852	            }
1853	            Expr::SuperCall(args) => {
1854	                self.load_internal("%func", Op::Callee);
1855	                self.load_internal("new.target", Op::NewTarget);
1856	                let has_spread = args.iter().any(|a| matches!(a, ArrayElem::Spread(_)));
1857	                if has_spread {
1858	                    self.compile_args_array(args)?;
1859	                    self.emit(Op::SuperCallArray);
1860	                } else {
1861	                    for a in args {
1862	                        if let ArrayElem::Expr(e) = a {
1863	                            self.compile_expr(e)?;
1864	                        }
1865	                    }
1866	                    self.emit(Op::SuperCall(args.len() as u32));
1867	                }
1868	                // bind this
1869	                self.bind_this_after_super()?;
1870	            }
1871	            Expr::Array(elems) => {
1872	                let simple = elems.iter().all(|e| matches!(e, Some(ArrayElem::Expr(_))));
1873	                if simple && elems.len() < 1024 {
1874	                    for el in elems {
1875	                        if let Some(ArrayElem::Expr(e)) = el {
1876	                            self.compile_expr(e)?;
1877	                        }
1878	                    }
1879	                    self.emit(Op::NewArray(elems.len() as u32));
1880	                } else {
1881	                    self.emit(Op::NewArray(0));
1882	                    for el in elems {
1883	                        match el {
1884	                            None => {
1885	                                self.emit(Op::ArrayHole);
1886	                            }
1887	                            Some(ArrayElem::Expr(e)) => {
1888	                                self.compile_expr(e)?;
1889	                                self.emit(Op::ArrayPush);
1890	                            }
1891	                            Some(ArrayElem::Spread(e)) => {
1892	                                self.compile_expr(e)?;
1893	                                self.emit(Op::ArraySpread);
1894	                            }
1895	                        }
1896	                    }
1897	                }
1898	            }
1899	            Expr::Object(props) => self.compile_object(props)?,
1900	            Expr::Function(f) => {
1901	                let idx = self.compile_function(f, None)?;
1902	                self.emit(Op::Closure(idx));
1903	            }
1904	            Expr::Arrow(f) => {
1905	                let idx = self.compile_function(f, None)?;
1906	                self.emit(Op::Closure(idx));
1907	            }
1908	            Expr::Class(c) => self.compile_class(c, None)?,
1909	            Expr::Unary(op, arg) => self.compile_unary(*op, arg)?,
1910	            Expr::Update { inc, prefix, target } => self.compile_update(*inc, *prefix, target)?,
1911	            Expr::Binary(op, a, b) => {
1912	                self.compile_expr(a)?;
1913	                self.compile_expr(b)?;
1914	                self.emit(binop(*op));
1915	            }
1916	            Expr::Logical(op, a, b) => {
1917	                let l = self.new_label();
1918	                self.compile_expr(a)?;
1919	                match op {
1920	                    LogicalOp::And => self.emit_jump(Op::JumpIfFalseKeep(0), l),
1921	                    LogicalOp::Or => self.emit_jump(Op::JumpIfTrueKeep(0), l),
1922	                    LogicalOp::Nullish => self.emit_jump(Op::JumpIfNotNullishKeep(0), l),
1923	                };
1924	                self.emit(Op::Pop);
1925	                self.compile_expr(b)?;
1926	                self.place(l);
1927	            }
1928	            Expr::Assign { op, target, value } => self.compile_assign(*op, target, value)?,
1929	            Expr::Cond(t, a, b) => {
1930	                let l_else = self.new_label();
1931	                let l_end = self.new_label();
1932	                self.compile_cond_jump(t, false, l_else)?;
1933	                self.compile_expr(a)?;
1934	                self.emit_jump(Op::Jump(0), l_end);
1935	                self.place(l_else);
1936	                self.compile_expr(b)?;
1937	                self.place(l_end);
1938	            }
1939	            Expr::Call { callee, args, optional } => {
1940	                self.compile_call(callee, args, *optional, None)?;
1941	            }
1942	            Expr::New { callee, args } => {
1943	                self.compile_expr(callee)?;
1944	                let has_spread = args.iter().any(|a| matches!(a, ArrayElem::Spread(_)));
1945	                if has_spread {
1946	                    self.compile_args_array(args)?;
1947	                    self.emit(Op::NewArray_);
1948	                } else {
1949	                    for a in args {
1950	                        if let ArrayElem::Expr(e) = a {
1951	                            self.compile_expr(e)?;
1952	                        }
1953	                    }
1954	                    self.emit(Op::New(args.len() as u32));
1955	                }
1956	            }
1957	            Expr::Member { obj, prop, optional } => {
1958	                self.compile_expr(obj)?;
1959	                if *optional {
1960	                    self.emit_opt_check(1)?;
1961	                }
1962	                self.compile_member_get(prop)?;
1963	            }
1964	            Expr::OptChain(inner) => {
1965	                let l_end = self.new_label();
1966	                let saved = self.f().opt_end.replace(l_end);
1967	                let r = self.compile_expr(inner);
1968	                self.f().opt_end = saved;
1969	                r?;
1970	                self.place(l_end);
1971	            }
1972	            Expr::Seq(v) => {
1973	                for (i, x) in v.iter().enumerate() {
1974	                    self.compile_expr(x)?;
1975	                    if i + 1 < v.len() {
1976	                        self.emit(Op::Pop);
1977	                    }
1978	                }
1979	            }
1980	            Expr::Yield { arg, delegate } => {
1981	                if *delegate {
1982	                    self.compile_expr(arg.as_ref().unwrap())?;
1983	                    let is_async = self.f().is_async;
1984	                    if is_async {
1985	                        self.emit(Op::GetAsyncIterator);
1986	                    } else {
1987	                        self.emit(Op::GetIterator);
1988	                    }
1989	                    self.emit(Op::Undef);
1990	                    let ret = self.new_label();
1991	                    let after = self.new_label();
1992	                    self.emit_jump(Op::YieldStar(0, is_async), ret);
1993	                    self.emit_jump(Op::Jump(0), after);
1994	                    self.place(ret);
1995	                    self.emit_return()?;
1996	                    self.place(after);
1997	                } else {
1998	                    match arg {
1999	                        Some(a) => self.compile_expr(a)?,

2000	                        None => {
2001	                            self.emit(Op::Undef);
2002	                        }
2003	                    }
2004	                    if self.f().is_async {
2005	                        // async generator: await the operand before yielding
2006	                        self.emit(Op::Await);
2007	                    }
2008	                    self.emit(Op::Yield);
2009	                    let ret = self.new_label();
2010	                    let after = self.new_label();
2011	                    self.emit_jump(Op::GenResume(0), ret);
2012	                    self.emit_jump(Op::Jump(0), after);
2013	                    self.place(ret);
2014	                    if self.f().is_async {
2015	                        self.emit(Op::Await);
2016	                    }
2017	                    self.emit_return()?;
2018	                    self.place(after);
2019	                }
2020	            }
2021	            Expr::Await(a) => {
2022	                self.compile_expr(a)?;
2023	                self.emit(Op::Await);
2024	            }
2025	            Expr::PrivateIn(n, obj) => {
2026	                self.load_name(&format!("#{}", n));
2027	                self.compile_expr(obj)?;
2028	                self.emit(Op::PrivateIn);
2029	            }
2030	            Expr::ImportCall(spec, opts) => {
2031	                self.compile_expr(spec)?;
2032	                match opts {
2033	                    Some(o) => self.compile_expr(o)?,
2034	                    None => {
2035	                        self.emit(Op::Undef);
2036	                    }
2037	                }
2038	                self.emit(Op::DynamicImport);
2039	            }
2040	            Expr::Paren(inner) => self.compile_expr(inner)?,
2041	        }
2042	        Ok(())
2043	    }
