2049	    /// optional-chain short circuit: if top of stack is nullish, pop `pops` values and push undefined,
2050	    /// then jump to the chain end.
2051	    fn emit_opt_check(&mut self, pops: u32) -> CResult<()> {
2052	        let end = match self.f().opt_end {
2053	            Some(l) => l,
2054	            None => return cerr("optional chain outside chain", 0),
2055	        };
2056	        let cont = self.new_label();
2057	        self.emit_jump(Op::JumpIfNotNullishKeep(0), cont);
2058	        for _ in 0..pops {
2059	            self.emit(Op::Pop);
2060	        }
2061	        self.emit(Op::Undef);
2062	        self.emit_jump(Op::Jump(0), end);
2063	        self.place(cont);
2064	        Ok(())
2065	    }
