2154	    fn compile_unary(&mut self, op: UnaryOp, arg: &'a Expr) -> CResult<()> {
2155	        match op {
2156	            UnaryOp::Typeof => {
2157	                if let Expr::Ident(id) = arg.unparen() {
2158	                    match self.resolve(&id.name) {
2159	                        Resolved::Global => {
2160	                            let k = self.key_idx(&id.name);
2161	                            self.emit(Op::TypeofGlobal(k));
2162	                            return Ok(());
2163	                        }
2164	                        Resolved::Dynamic => {
2165	                            let k = self.key_idx(&id.name);
2166	                            self.emit(Op::TypeofName(k));
2167	                            return Ok(());
2168	                        }
2169	                        _ => {}
2170	                    }
2171	                }
2172	                self.compile_expr(arg)?;
2173	                self.emit(Op::Typeof);
2174	            }
2175	            UnaryOp::Delete => match arg.unparen() {
2176	                Expr::Member { obj, prop, optional } => {
2177	                    self.compile_expr(obj)?;
2178	                    if *optional {
2179	                        self.emit_opt_check_bool(1)?;
2180	                    }
2181	                    match prop {
2182	                        MemberProp::Name(n) => {
2183	                            let k = self.key_idx(n);
2184	                            self.emit(Op::DeleteProp(k));
2185	                        }
2186	                        MemberProp::Computed(k) => {
2187	                            self.compile_expr(k)?;
2188	                            self.emit(Op::DeleteElem);
2189	                        }
2190	                        MemberProp::Private(_) => return cerr("private fields cannot be deleted", 0),
2191	                    }
2192	                }
2193	                Expr::OptChain(inner) => {
2194	                    let l_end = self.new_label();
2195	                    let saved = self.f().opt_end.replace(l_end);
2196	                    let r = self.compile_unary(UnaryOp::Delete, inner);
2197	                    self.f().opt_end = saved;
2198	                    r?;
2199	                    self.place(l_end);
2200	                }
2201	                Expr::Ident(id) => match self.resolve(&id.name) {
2202	                    Resolved::Global | Resolved::Dynamic => {
2203	                        let k = self.key_idx(&id.name);
2204	                        self.emit(Op::DeleteName(k));
2205	                    }
2206	                    _ => {
2207	                        self.emit(Op::False);
2208	                    }
2209	                },
2210	                Expr::SuperMember(_) => {
2211	                    self.emit(Op::ThisChk);
2212	                    self.emit(Op::Pop);
2213	                    let s = self.string_idx("Unsupported reference to 'super'");
2214	                    self.emit(Op::ThrowRef(s));
2215	                }
2216	                other => {
2217	                    self.compile_expr(other)?;
2218	                    self.emit(Op::Pop);
2219	                    self.emit(Op::True);
2220	                }
2221	            },
2222	            _ => {
2223	                self.compile_expr(arg)?;
2224	                self.emit(match op {
2225	                    UnaryOp::Neg => Op::Neg,
2226	                    UnaryOp::Plus => Op::Plus,
2227	                    UnaryOp::Not => Op::Not,
2228	                    UnaryOp::BitNot => Op::BitNot,
2229	                    UnaryOp::Void => Op::Void,
2230	                    _ => unreachable!(),
2231	                });
2232	            }
2233	        }
2234	        Ok(())
2235	    }
