2237	    /// like emit_opt_check but the short-circuit value is `true` (for delete)
2238	    fn emit_opt_check_bool(&mut self, pops: u32) -> CResult<()> {
2239	        let end = match self.f().opt_end {
2240	            Some(l) => l,
2241	            None => return cerr("optional chain outside chain", 0),
2242	        };
2243	        let cont = self.new_label();
2244	        self.emit_jump(Op::JumpIfNotNullishKeep(0), cont);
2245	        for _ in 0..pops {
2246	            self.emit(Op::Pop);
2247	        }
2248	        self.emit(Op::True);
2249	        self.emit_jump(Op::Jump(0), end);
2250	        self.place(cont);
