2254	    fn compile_update(&mut self, inc: bool, prefix: bool, target: &'a Expr) -> CResult<()> {
2255	        let op = if inc { Op::Inc } else { Op::Dec };
2256	        match target.unparen() {
2257	            Expr::Ident(id) => {
