2599	    /// compile callee producing [this, func]
2600	    fn compile_callee(&mut self, callee: &'a Expr) -> CResult<()> {
2601	        match callee {
2602	            Expr::Paren(inner) if matches!(inner.unparen(), Expr::Member { .. } | Expr::SuperMember(_)) => {
2603	                self.compile_callee(inner.unparen())
2604	            }
2605	            Expr::Member { obj, prop, optional } => {
2606	                self.compile_expr(obj)?;
2607	                if *optional {
2608	                    self.emit_opt_check(1)?;
2609	                }
2610	                match prop {
2611	                    MemberProp::Name(n) => {
2612	                        let k = self.key_idx(n);
2613	                        self.emit(Op::GetMethod(k));
2614	                    }
2615	                    MemberProp::Computed(k) => {
2616	                        self.compile_expr(k)?;
2617	                        self.emit(Op::GetMethodElem);
2618	                    }
2619	                    MemberProp::Private(n) => {
2620	                        self.emit(Op::Dup);
2621	                        self.load_name(&format!("#{}", n));
2622	                        self.emit(Op::GetPrivate);
2623	                    }
2624	                }
2625	                Ok(())
2626	            }
2627	            Expr::SuperMember(prop) => {
2628	                self.load_this();
2629	                self.emit(Op::Dup);
2630	                match prop {
2631	                    MemberProp::Name(n) => {
2632	                        let k = self.key_idx(n);
2633	                        self.emit(Op::GetSuper(k));
2634	                    }
2635	                    MemberProp::Computed(k) => {
2636	                        self.compile_expr(k)?;
2637	                        self.emit(Op::ToPropKey);
2638	                        self.emit(Op::GetSuperElem);
2639	                    }
2640	                    _ => return cerr("unexpected private", 0),
2641	                }
2642	                Ok(())
2643	            }
2644	            Expr::Ident(id) => {
2645	                match self.resolve(&id.name) {
2646	                    Resolved::Dynamic => {
2647	                        let k = self.key_idx(&id.name);
2648	                        self.emit(Op::GetNameCall(k));
2649	                    }
2650	                    _ => {
2651	                        self.emit(Op::Undef);
2652	                        if &*id.name == "arguments" {
2653	                            self.load_arguments();
2654	                        } else {
2655	                            self.load_name(&id.name);
2656	                        }
2657	                    }
2658	                }
2659	                Ok(())
2660	            }
2661	            Expr::OptChain(_) => {
2662	                self.emit(Op::Undef);
2663	                self.compile_expr(callee)
2664	            }
2665	            other => {
2666	                self.emit(Op::Undef);
2667	                self.compile_expr(other)
2668	            }
2669	        }
2670	    }
