2672	    fn callee_desc(&mut self, callee: &Expr) -> u32 {
2673	        match callee {
2674	            Expr::Ident(id) => self.string_idx(&id.name),
2675	            Expr::Paren(inner) => match inner.unparen() {
2676	                Expr::Ident(id) => self.string_idx(&id.name),
2677	                Expr::Member { prop: MemberProp::Name(n), .. } => self.string_idx(&format!("(intermediate value).{}", n)),
2678	                _ => self.string_idx("expression"),
2679	            },
2680	            Expr::Member { prop: MemberProp::Name(n), .. } => self.string_idx(&format!("(intermediate value).{}", n)),
2681	            Expr::SuperMember(_) => u32::MAX,
2682	            _ => self.string_idx("expression"),
2683	        }
2684	    }
