2686	    fn compile_args_array(&mut self, args: &'a [ArrayElem]) -> CResult<()> {
2687	        self.emit(Op::NewArray(0));
2688	        for a in args {
2689	            match a {
2690	                ArrayElem::Expr(e) => {
2691	                    self.compile_expr(e)?;
2692	                    self.emit(Op::ArrayPush);
2693	                }
2694	                ArrayElem::Spread(e) => {
2695	                    self.compile_expr(e)?;
2696	                    self.emit(Op::ArraySpread);
2697	                }
2698	            }
2699	        }

2700	        Ok(())
2701	    }
