2703	    fn compile_call(&mut self, callee: &'a Expr, args: &'a [ArrayElem], optional: bool, _x: Option<()>) -> CResult<()> {
2704	        let is_direct_eval = matches!(callee.unparen(), Expr::Ident(id) if &*id.name == "eval")
2705	            && matches!(self.resolve("eval"), Resolved::Global | Resolved::Dynamic);
2706	        let desc = self.callee_desc(callee);
2707	        self.compile_callee(callee)?;
2708	        if optional {
2709	            self.emit_opt_check(2)?;
2710	        }
2711	        let has_spread = args.iter().any(|a| matches!(a, ArrayElem::Spread(_)));
2712	        if has_spread {
2713	            self.compile_args_array(args)?;
2714	            if is_direct_eval {
2715	                self.emit(Op::CallEvalArray);
2716	            } else {
2717	                self.emit(Op::CallArray(desc));
2718	            }
2719	        } else {
2720	            for a in args {
2721	                if let ArrayElem::Expr(e) = a {
2722	                    self.compile_expr(e)?;
2723	                }
2724	            }
2725	            if is_direct_eval {
2726	                self.emit(Op::CallEval(args.len() as u32));
2727	            } else {
2728	                self.emit(Op::Call(args.len() as u32, desc));
2729	            }
2730	        }
2731	        Ok(())
2732	    }
