2734	    fn compile_object(&mut self, props: &'a [PropDef]) -> CResult<()> {
2735	        self.emit(Op::NewObject);
2736	        for p in props {
2737	            match p {
2738	                PropDef::KeyValue(key, v) => match key {
2739	                    PropKey::Computed(k) => {
2740	                        self.compile_expr(k)?;
2741	                        self.emit(Op::ToPropKey);
2742	                        self.compile_expr(v)?;
2743	                        if v.is_anonymous_fn() {
2744	                            self.emit(Op::SetFunctionName(0));
2745	                        }
2746	                        self.emit(Op::DefineFieldComputed);
2747	                    }
2748	                    k => {
2749	                        let name = propkey_static_name(k).unwrap();
2750	                        let hint = if v.is_anonymous_fn() { Some(JsStr::from_str(&name)) } else { None };
2751	                        self.compile_expr_named(v, hint)?;
2752	                        let ki = match k {
2753	                            PropKey::Str(u) => self.key_idx_units(u),
2754	                            _ => self.key_idx(&name),
2755	                        };
2756	                        self.emit(Op::DefineField(ki));
2757	                    }
2758	                },
2759	                PropDef::Shorthand(id) => {
2760	                    if &*id.name == "arguments" {
2761	                        self.load_arguments();
2762	                    } else {
2763	                        self.load_name(&id.name);
2764	                    }
2765	                    let k = self.key_idx(&id.name);
2766	                    self.emit(Op::DefineField(k));
2767	                }
2768	                PropDef::Proto(v) => {
2769	                    self.compile_expr(v)?;
2770	                    self.emit(Op::SetProtoLit);
2771	                }
2772	                PropDef::Spread(e) => {
2773	                    self.compile_expr(e)?;
2774	                    self.emit(Op::CopyDataProps);
2775	                }
2776	                PropDef::Method { key, func, kind } => {
2777	                    let mk = match kind {
2778	                        MethodKind::Method => MKind::Method,
2779	                        MethodKind::Getter => MKind::Getter,
2780	                        MethodKind::Setter => MKind::Setter,
2781	                    };
2782	                    match key {
2783	                        PropKey::Computed(k) => {
2784	                            self.compile_expr(k)?;
2785	                            self.emit(Op::ToPropKey);
2786	                            let idx = self.compile_function(func, None)?;
2787	                            // [obj key] -> method with home obj
2788	                            self.emit(Op::Pick(1));
2789	                            self.emit(Op::Method(idx));
2790	                            // [obj key obj fn]
2791	                            self.emit(Op::Swap);
2792	                            self.emit(Op::Pop);
2793	                            // [obj key fn]
2794	                            match mk {
2795	                                MKind::Method => {
2796	                                    self.emit(Op::SetFunctionName(0));
2797	                                    self.emit(Op::DefineFieldComputed);
2798	                                }
2799	                                MKind::Getter => {
2800	                                    self.emit(Op::SetFunctionName(1));
2801	                                    self.emit(Op::DefineAccessorComputed(MKind::Getter));
2802	                                }
2803	                                MKind::Setter => {
2804	                                    self.emit(Op::SetFunctionName(2));
2805	                                    self.emit(Op::DefineAccessorComputed(MKind::Setter));
2806	                                }
2807	                            }
2808	                        }
2809	                        k => {
2810	                            let name = propkey_static_name(k).unwrap();
2811	                            let fname = match mk {
2812	                                MKind::Method => name.clone(),
2813	                                MKind::Getter => format!("get {}", name),
2814	                                MKind::Setter => format!("set {}", name),
2815	                            };
2816	                            let idx = self.compile_function(func, Some(JsStr::from_str(&fname)))?;
2817	                            self.emit(Op::Method(idx));
2818	                            // [obj fn]
2819	                            let ki = match k {
2820	                                PropKey::Str(u) => self.key_idx_units(u),
2821	                                _ => self.key_idx(&name),
2822	                            };
2823	                            match mk {
2824	                                MKind::Method => {
2825	                                    self.emit(Op::DefineField(ki));
2826	                                }
2827	                                MKind::Getter | MKind::Setter => {
2828	                                    self.emit(Op::DefineAccessor(ki, mk));
2829	                                }
