2841	    /// Compile a nested function; returns its index in the current function's funcs table.
2842	    fn compile_function(&mut self, f: &'a Function, name_hint: Option<JsStr>) -> CResult<u32> {
2843	        let code = self.compile_function_code(f, name_hint)?;
