2849	    fn compile_function_code(&mut self, f: &'a Function, name_hint: Option<JsStr>) -> CResult<Rc<FunctionCode>> {
2850	        let rid = f.scope.get() as usize;
2851	        let is_arrow = f.kind == FuncKind::Arrow;
2852	        // named function expression scope
2853	        let has_name_scope = f.is_expr && f.name.is_some() && f.kind == FuncKind::Normal;
2854	        let mut name_scope_pushed = false;
2855	        if has_name_scope {
2856	            // the name scope is the parent of the function scope in the resolver
2857	            let parent = self.rscope(rid).parent.unwrap();
2858	            let ps = self.rscope(parent);
2859	            if ps.kind == ScopeKind::FuncName {
2860	                // a FuncName scope's binding is captured if referenced inside: it lives in an env
2861	                // created when the closure is made. We represent it as an env scope entered in the
2862	                // *inner* function prologue instead (the closure value itself).
2863	                name_scope_pushed = true;
2864	            }
2865	        }
2866	        let mut fs = FuncState::new(f.kind, is_arrow, f.is_async, f.is_generator, f.strict, rid);
2867	        fs.is_arrow = is_arrow;
2868	        self.fs.push(fs);
2869	        if name_scope_pushed {
2870	            let parent = self.rscope(rid).parent.unwrap();
2871	            let ps = self.rscope(parent);
2872	            let d = &ps.decls[0];
2873	            // own name binding: store as local (or env if captured) initialized to callee
2874	            let st = if d.captured {
2875	                let info = Rc::new(ScopeInfo { names: vec![JsStr::from_str(&d.name)], kinds: vec![BindKind::FuncName], is_function: false });
2876	                let fst = self.f();
2877	                fst.scope_infos.push(info);
2878	                let idx = (fst.scope_infos.len() - 1) as u32;
2879	                self.emit(Op::PushScope(idx));
2880	                Storage::Env(0)
2881	            } else {
2882	                Storage::Local(self.new_local())
2883	            };
2884	            self.f().scopes.push(CScope {
2885	                rid: parent,
2886	                has_env: d.captured,
2887	                names: vec![(d.name.clone(), st, BindKind::FuncName)],
2888	                is_with: false,
2889	                dyn_eval: false,
2890	            });
2891	            self.emit(Op::Callee);
2892	            match st {
2893	                Storage::Local(s) => {
2894	                    self.emit(Op::InitLocal(s));
2895	                }
2896	                Storage::Env(s) => {
2897	                    self.emit(Op::InitEnv(0, s));
2898	                }
2899	            }
2900	        }
2901	        let rs = self.rscope(rid);
2902	        let force_env = rs.has_eval || rs.contains_eval;
2903	        self.enter_scope(rid, force_env);
2904	        self.init_internal_bindings(rid);
2905	        // parameters
2906	        let mut length = 0u32;
2907	        let mut seen_default = false;
2908	        for (i, p) in f.params.iter().enumerate() {
2909	            if p.rest {
2910	                self.emit(Op::GetRest(i as u32));
2911	                seen_default = true;
2912	            } else {
2913	                self.emit(Op::GetArg(i as u32));
2914	                if let Some(d) = &p.default {
2915	                    seen_default = true;
2916	                    let l = self.new_label();
2917	                    self.emit(Op::Dup);
2918	                    self.emit_jump(Op::JumpIfNotUndef(0), l);
2919	                    self.emit(Op::Pop);
2920	                    let hint = match &p.pat {
2921	                        Pattern::Ident(id) if d.is_anonymous_fn() => Some(JsStr::from_str(&id.name)),
2922	                        _ => None,
2923	                    };
2924	                    self.compile_expr_named(d, hint)?;
2925	                    self.place(l);
2926	                } else if !seen_default {
2927	                    length += 1;
2928	                }
2929	            }
2930	            match &p.pat {
2931	                Pattern::Ident(id) => {
2932	                    // params are var-like (mutable)
2933	                    match self.resolve(&id.name) {
2934	                        Resolved::Local(s, _) => {
2935	                            self.emit(Op::InitLocal(s));
2936	                        }
2937	                        Resolved::Env(d, s, _) => {
2938	                            self.emit(Op::InitEnv(d, s));
2939	                        }
2940	                        _ => {
2941	                            self.init_name(&id.name);
2942	                        }
2943	                    }
2944	                }
2945	                other => self.compile_pattern(other, Some(VarKind::Let))?,
2946	            }
2947	        }
2948	        // `arguments` when shadowed by nothing is created in init_internal_bindings
2949	        self.hoist_functions(&f.body, true)?;
2950	        if f.is_generator {
2951	            self.emit(Op::GenStart);
2952	        }
2953	        for s in &f.body {
2954	            self.compile_stmt(s)?;
2955	        }
2956	        self.emit(Op::Undef);
2957	        if f.kind == FuncKind::DerivedConstructor {
2958	            self.emit_return()?;
2959	        } else {
2960	            self.emit(Op::Return);
2961	        }
2962	        self.exit_scope_noemit();
2963	        if name_scope_pushed {
2964	            self.f().scopes.pop();
2965	        }
2966	        let fs = self.fs.pop().unwrap();
2967	        let name = match (&f.name, name_hint) {
2968	            (Some(n), _) => JsStr::from_str(&n.name),
2969	            (None, Some(h)) => h,
2970	            (None, None) => JsStr::empty(),
2971	        };
2972	        let mut code = self.finish(fs, name, length, f.src_start, f.src_end, f.line, f.simple_params);
2973	        code.no_prototype = !matches!(f.kind, FuncKind::Normal | FuncKind::ClassConstructor | FuncKind::DerivedConstructor) || (f.is_async && !f.is_generator);
2974	        Ok(Rc::new(code))
2975	    }
