fn dv_view_len(vm: &mut Vm, buf: &Rc<RefCell<BufferData>>, off: usize, len: Option<usize>) -> JsResult<usize> {
    let b = buf.borrow();
    if b.detached {
        drop(b);
        return vm.throw_type("Cannot perform DataView operation on a detached ArrayBuffer");
    }
    let bl = b.bytes.len();
    match len {
        Some(l) => {
            if off + l > bl {
                drop(b);
                return vm.throw_type("DataView is out of bounds");
            }
            Ok(l)
        }
        None => {
            if off > bl {
                drop(b);
                return vm.throw_type("DataView is out of bounds");
            }
            Ok(bl - off)
        }
    }
}

