fn dv_get(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let kind = kind_from_slot(a);
    let (_, buf, off, len) = this_dv(vm, &a.this)?;
    let idx = vm.to_index(&a.arg(0))?;
    let little = a.arg(1).truthy();
    let vl = dv_view_len(vm, &buf, off, len)?;
    if idx + kind.size() > vl {
