fn ta_to_reversed(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let (o, k, len) = this_ta(vm, &a.this)?;
    let mut vals = ta_values_vec(&o);
    vals.reverse();
    let r = create_typed_array(vm, k, len, None)?;
    fill_from_values(vm, &r, &vals)?;
    Ok(Value::Obj(r))
