    let (o, _, len) = this_ta(vm, &a.this)?;
    let n = vm.to_integer_or_infinity(&a.arg(0))?;
    let k = if n >= 0.0 { n } else { len as f64 + n };
    if k < 0.0 || k >= len as f64 {
        return Ok(Value::Undefined);
    }
    Ok(ta_get(&o, k as usize))
