    let (o, _, len) = this_ta(vm, &a.this)?;
    let to = rel(vm, &a.arg(0), len, 0)?;
    let from = rel(vm, &a.arg(1), len, 0)?;
    let fin = rel(vm, &a.arg(2), len, len)?;
