pub fn for_in_next(&mut self, it: &Obj) -> JsResult<Option<JsStr>> {
    loop {
        // take state out
        let (obj, started) = {
            let b = it.borrow();
            match &b.kind {
                ObjKind::Iterator(s) => match &**s {
                    IterState::ForIn { obj, started, .. } => (obj.clone(), *started),
                    _ => return Ok(None),
                },
                _ => return Ok(None),
            }
        };
        let obj = match obj {
            Some(o) => o,
            None => return Ok(None),
        };
        if !started {
            let keys = self.own_property_keys(&obj)?;
            let mut strs = Vec::new();
            for k in keys {
                if let PropKey::Str(s) = k {
                    strs.push(s);
                }
            }
            if let ObjKind::Iterator(s) = &mut it.borrow_mut().kind {
                if let IterState::ForIn { keys, index, started, .. } = &mut **s {
                    *keys = strs;
                    *index = 0;
                    *started = true;
                }
            }
        }
        // next key
        let next_key = {
            let mut b = it.borrow_mut();
            match &mut b.kind {
                ObjKind::Iterator(s) => match &mut **s {
                    IterState::ForIn { keys, index, .. } => {
                        if *index < keys.len() {
                            *index += 1;
                            Some(keys[*index - 1].clone())
                        } else {
                            None
                        }
                    }
                    _ => None,
                },
                _ => None,
            }
        };
        match next_key {
            Some(k) => {
                let pk = PropKey::Str(k.clone());
                let visited = match &it.borrow().kind {
                    ObjKind::Iterator(s) => match &**s {
                        IterState::ForIn { visited, .. } => visited.contains(&k),
                        _ => false,
                    },
                    _ => false,
                };
                if visited {
                    continue;
                }
                let desc = self.get_own_property(&obj, &pk)?;
                match desc {
                    Some(d) => {
                        if let ObjKind::Iterator(s) = &mut it.borrow_mut().kind {
                            if let IterState::ForIn { visited, .. } = &mut **s {
                                visited.push(k.clone());
                            }
                        }
                        if d.enumerable == Some(true) {
                            return Ok(Some(k));
                        }
                    }
                    None => continue,
                }
            }
            None => {
                // move to prototype
                let p = self.get_prototype_of(&obj)?;
                if let ObjKind::Iterator(s) = &mut it.borrow_mut().kind {
                    if let IterState::ForIn { obj: o, started, .. } = &mut **s {
                        *o = p.clone();
                        *started = false;
                    }
                }
                if p.is_none() {
                    return Ok(None);
                }
            }
        }
    }
}

