fn parse_array_literal(&mut self) -> PResult<Expr> {
    self.advance()?; // [
    let mut elems = Vec::new();
    loop {
        if self.is_punct("]") {
            break;
        }
        if self.is_punct(",") {
            self.advance()?;
            elems.push(None);
            continue;
        }
        let el = if self.eat_punct("...")? {
            ArrayElem::Spread(self.parse_assign(false)?)
        } else {
            ArrayElem::Expr(self.parse_assign(false)?)
        };
        elems.push(Some(el));
        if self.is_punct("]") {
            break;
        }
        if !self.is_punct(",") {
            return self.err("expected ']'");
        }
        self.advance()?;
    }
    self.advance()?; // ]
    Ok(Expr::Array(elems))
}

