let n = 0, running = false;
function startTicks() { n = 0; running = true; const step = () => { if (!running) return; n++; Promise.resolve().then(step); }; Promise.resolve().then(step); }
async function measure(name, fn) {
  startTicks();
  try { const r = await fn(); running = false; console.log(name, 'ticks', n, typeof r); }
  catch (e) { running = false; console.log(name, 'ticks', n, 'threw', e && e.message); }
  await new Promise(r => setTimeout(r, 1));
}
(async () => {
  await measure('mjs', () => import('./m.mjs'));
  await measure('mjs-again', () => import('./m.mjs'));
  await measure('cjs', () => import('./sub/c.js'));
  await measure('builtin', () => import('node:path'));
  await measure('notfound', () => import('./nope.mjs'));
  await measure('json', () => import('./data.json', { with: { type: 'json' } }));
  await measure('syntaxerr', () => import('./sub/esm.js'));
})();

