    let fs = self.fs.pop().unwrap();
    let mut code = self.finish(fs, JsStr::empty(), 0, 0, 0, 0, true);
    code.is_script = true;
    code.is_eval = is_eval;
    Ok(Rc::new(code))
}

fn exit_scope_noemit(&mut self) {
    self.f().scopes.pop();
