    if d <= 0 or r < 0.3:
        return random.choice(VARS + ['0', '1', '2', '3', '-1'])
    if r < 0.4:
        return '(' + aexpr(d - 1) + ' ? ' + aexpr(d - 1) + ' : ' + aexpr(d - 1) + ')'
    if r < 0.45:
        return '(' + random.choice(VARS) + '++)'
    op = random.choice(['+', '-', '*', '%', '&', '|', '^', '<<', '>>'])
    e = '(' + aexpr(d - 1) + ' ' + op + ' ' + aexpr(d - 1) + ')'
    if op in ('*', '<<'):
        e = '(' + e + ' % 1000)'
    return e

def cond():
    op = random.choice(['<', '>', '<=', '>=', '===', '!=='])
    return aexpr(1) + ' ' + op + ' ' + aexpr(1)

def block(d, ctx, k=None):
