        k = random.randint(1, 3)
    return '{ ' + ' '.join(stmt(d - 1, ctx) for _ in range(k)) + ' }'

def stmt(d, ctx):
    # ctx: dict with 'loops' (list of labels or None), 'fn' (in function), 'gen' (in generator)
    choices = ['assign', 'print', 'print']
    if d > 0:
        choices += ['if', 'for', 'while', 'do', 'try', 'switch', 'block', 'forof', 'labeled', 'closure', 'fn']
        if ctx['gen']:
            choices += ['yield']
    if ctx['loops']:
        choices += ['break', 'continue']
    if ctx['fn']:
        choices += ['return']
    c = random.choice(choices)
    if c == 'assign':
        v = random.choice(VARS)
        op = random.choice(['=', '+=', '-=', '|=', '^='])
        return '%s %s %s;' % (v, op, aexpr())
    if c == 'print':
        return 'p(%s);' % aexpr()
    if c == 'if':
        s = 'if (%s) %s' % (cond(), block(d, ctx))
        if random.random() < 0.5:
            s += ' else ' + block(d, ctx)
        return s
    if c == 'block':
        v = random.choice(VARS)
        return '{ let %s = %s; %s }' % (v, aexpr(), ' '.join(stmt(d - 1, ctx) for _ in range(2)))
    if c == 'for':
        i = fresh('i')
        lbl = fresh('L') if random.random() < 0.3 else None
        nctx = dict(ctx, loops=ctx['loops'] + [lbl])
        s = 'for (let %s = 0; %s < %d; %s++) { p("%s" + %s); %s }' % (i, i, random.randint(0, 3), i, i, i, ' '.join(stmt(d - 1, nctx) for _ in range(random.randint(1, 3))))
        if lbl:
            s = lbl + ': ' + s
        return s
    if c == 'forof':
        x = fresh('x')
        nctx = dict(ctx, loops=ctx['loops'] + [None])
        return 'for (const %s of [%s]) { p(%s); %s }' % (x, ', '.join(aexpr(1) for _ in range(random.randint(0, 3))), x, ' '.join(stmt(d - 1, nctx) for _ in range(random.randint(1, 2))))
    if c == 'while':
        g = fresh('g')
        nctx = dict(ctx, loops=ctx['loops'] + [None])
        return 'let %s = %d; while (%s-- > 0) %s' % (g, random.randint(0, 3), g, block(d, nctx))
    if c == 'do':
        g = fresh('g')
        nctx = dict(ctx, loops=ctx['loops'] + [None])
        return 'let %s = %d; do %s while (%s-- > 0);' % (g, random.randint(0, 2), block(d, nctx), g)
    if c == 'labeled':
        lbl = fresh('B')
        # labeled block: break only
        inner = ' '.join(stmt(d - 1, ctx) for _ in range(2))
        return '%s: { %s if (%s) break %s; p("after-%s"); }' % (lbl, inner, cond(), lbl, lbl)
    if c == 'try':
        s = 'try { %s if (%s) throw new Error("e" + a); %s }' % (stmt(d - 1, ctx), cond(), stmt(d - 1, ctx))
        r = random.random()
        if r < 0.4:
            s += ' catch (err) { p(err.message); %s }' % stmt(d - 1, ctx)
        elif r < 0.7:
            s += ' catch (err) { p(err.message); } finally { p("fin"); %s }' % stmt(d - 1, dict(ctx))
        else:
            s = 'try { %s } finally { p("fin2"); }' % s.replace('try ', '', 1) if False else s + ' catch { p("caught") } finally { p("fin3") }'
        return s
    if c == 'switch':
        nctx = dict(ctx, loops=ctx['loops'] + ['__switch'])
        cases = []
        for k in range(random.randint(1, 3)):
            body = ' '.join(stmt(d - 1, nctx) for _ in range(random.randint(0, 2)))
            if random.random() < 0.6:
                body += ' break;'
            cases.append('case %d: %s' % (k, body))
        if random.random() < 0.5:
            cases.append('default: p("dflt");')
        return 'switch (%s & 3) { %s }' % (aexpr(1), ' '.join(cases))
    if c == 'closure':
        i = fresh('j')
        return 'for (let %s = 0; %s < 2; %s++) fns.push(() => %s * 10 + %s);' % (i, i, i, i, random.choice(VARS))
    if c == 'fn':
        f = fresh('f')
        if random.random() < 0.3:
            body = ' '.join(stmt(d - 1, {'loops': [], 'fn': True, 'gen': True}) for _ in range(random.randint(1, 3)))
            return 'function* %s() { %s yield a; } p([...%s()].join("/"));' % (f, body, f)
        body = ' '.join(stmt(d - 1, {'loops': [], 'fn': True, 'gen': False}) for _ in range(random.randint(1, 3)))
        return 'function %s() { %s return "end"; } p(%s());' % (f, body, f)
    if c == 'yield':
        return 'yield %s;' % aexpr(1)
    if c == 'return':
        return 'return %s;' % aexpr(1)
    if c == 'break' or c == 'continue':
        loops = ctx['loops']
        # find valid targets
        if c == 'continue':
            # continue only targets loops (not switch); if innermost is switch, need a loop outside
            cands = [l for l in loops if l != '__switch']
            if not cands:
                return 'p("nc");'
            # unlabeled continue valid if any loop exists
            lbl = random.choice(cands + [None])
            if lbl is None:
                return 'if (%s) continue;' % cond()
            return 'if (%s) continue %s;' % (cond(), lbl)
        lbls = [l for l in loops if l and l != '__switch']
        if lbls and random.random() < 0.4:
            return 'if (%s) break %s;' % (cond(), random.choice(lbls))
        return 'if (%s) break;' % cond()
    return ';'

