import subprocess, sys, re
# usage: difflines.py file.js [header_lines] -- print source lines whose output differs (outputs prefixed by index)
LUMEN = '/workspace/.claude/worktrees/agent-ac59a005e41a4405b/target/release/lumen'
f = sys.argv[1]
nh = int(sys.argv[2]) if len(sys.argv) > 2 else 2
skip = sys.argv[3].split(',') if len(sys.argv) > 3 else []
src = open(f).read().split('\n')
def run(exe):
    try:
        r = subprocess.run([exe, f], capture_output=True, timeout=20)
        out = r.stdout.decode('utf-8', 'replace')
    except subprocess.TimeoutExpired:
        out = ''
    d = {}
    for line in out.split('\n'):
        m = re.match(r'^(\d+) (.*)$', line)
        if m:
            d[int(m.group(1))] = m.group(2)
    return d
a = run('/tmp/orig')
b = run(LUMEN)
for i in sorted(set(a) | set(b)):
    if a.get(i) != b.get(i):
        if i not in a:
            continue
        line = src[nh + i] if nh + i < len(src) else '?'
        if any(s in (a.get(i) or '') for s in skip if s):
            continue
        print('SRC :', line[:200])
        print('ORIG:', (a.get(i) or '')[:200])
        print('OURS:', (b.get(i) or '')[:200])

