fn fa_fail(vm: &mut Vm, st: &Value, e: Value, close: bool) {
    let (cap, iter) = {
        let b = fa_state(st);
        let s = match &b.kind {
            ObjKind::Host(h) => h.downcast_ref::<FromAsync>().unwrap(),
            _ => unreachable!(),
        };
        (s.cap.clone(), s.iter.clone())
    };
    if close {
        if let Some((it, _)) = iter {
            let _ = vm.iterator_close(&it);
        }
    }
    let _ = vm.call(&cap.reject, Value::Undefined, &[e]);
}

/// Request the next element and await it.
fn fa_step(vm: &mut Vm, st: &Value) {
    let (iter, array_like, idx, cap, arr, is_async) = {
        let b = fa_state(st);
        let s = match &b.kind {
            ObjKind::Host(h) => h.downcast_ref::<FromAsync>().unwrap(),
            _ => unreachable!(),
        };
        (s.iter.clone(), s.array_like.clone(), s.index.get(), s.cap.clone(), s.arr.clone(), s.is_async_iter)
    };
    if let (Some((it, next)), false) = (&iter, is_async) {
        // sync iterables: step synchronously and await only the value (like the reference)
        let r = match vm.call(next, it.clone(), &[]) {
            Ok(r) => r,
            Err(e) => return fa_fail(vm, st, e, false),
        };
