    pub fn native_closure(&self, name: &str, len: u32, f: NativeFn, slots: Vec<Value>) -> Obj {
        let o = self.native_fn(name, len, f);
        if let ObjKind::Native(n) = &mut o.borrow_mut().kind {
            n.slots = slots;
