fn advance(&mut self) -> PResult<Token> {
    let next = self.lex.next_token()?;
    let old = std::mem::replace(&mut self.tok, next);
    self.prev_end = old.end;
    self.prev_line = old.line;
    Ok(old)
}

fn is_punct(&self, p: &str) -> bool {
    matches!(&self.tok.tok, Tok::Punct(q) if *q == p)
}
fn is_kw(&self, k: &str) -> bool {
    matches!(&self.tok.tok, Tok::Keyword(q) if *q == k)
}
fn is_ident_named(&self, n: &str) -> bool {
    matches!(&self.tok.tok, Tok::Ident(q) if q == n) && !self.tok.escaped
}
fn eat_punct(&mut self, p: &str) -> PResult<bool> {
    if self.is_punct(p) {
        self.advance()?;
        Ok(true)
    } else {
        Ok(false)
    }
}
fn expect_punct(&mut self, p: &str) -> PResult<()> {
    if self.is_punct(p) {
        self.advance()?;
        Ok(())
    } else {
        self.err(format!("expected '{}'", p))
    }
}
fn eat_kw(&mut self, k: &str) -> PResult<bool> {
    if self.is_kw(k) {
        self.advance()?;
        Ok(true)
    } else {
        Ok(false)
    }
}

fn save(&self) -> SavedState {
    SavedState {
        pos: self.lex.pos,
        line: self.lex.line,

    while let Some(c) = self.peek() {
        if is_line_term(c) {
            break;
        }
        self.pos += 1;
    }
}

fn mk(&self, tok: Tok, start: usize, line: u32, nl: bool) -> Token {
    Token { tok, start, end: self.pos, line, nl_before: nl, escaped: false, octal_escape: false, legacy_octal: false }
}

