            Ok(run_repl_await(vm, frame, v))
        }
        Ok(_) => Ok(Value::Undefined),
        Err(e) => Err(Err(e)),
    }
}

/// Run a global script and return its completion value (`$262.evalScript`).
pub fn run_script_completion(vm: &mut Vm, src: &str) -> Result<Value, Result<SyntaxErr, Value>> {
    let prog = parser::parse(src, false).map_err(|e| Ok(SyntaxErr { msg: e.msg, line: e.line }))?;
    let mut res = Resolver::new();
    res.resolve_program(&prog, ScopeKind::Script).map_err(|e| Ok(SyntaxErr { msg: e.msg, line: e.line }))?;
    let comp = Compiler::new(&res, prog.source.clone(), false);
    let code = comp.compile_script(&prog, false, true, false).map_err(|e| Ok(SyntaxErr { msg: e.msg, line: e.line }))?;
