pub fn parse_expression(&mut self, no_in: bool) -> PResult<Expr> {
    let e = self.parse_assign(no_in)?;
    if self.is_punct(",") {
        let mut v = vec![e];
        while self.eat_punct(",")? {
            v.push(self.parse_assign(no_in)?);
        }
        self.check_no_cover_init()?;
        return Ok(Expr::Seq(v));
    }
    self.check_no_cover_init()?;
    Ok(e)
}

